ALTER TABLE public.team_invitations ADD CONSTRAINT team_invitations_email_check CHECK (((email = lower(btrim(email))) AND (email <> ''::text)));
ALTER TABLE public.team_invitations ADD CONSTRAINT team_invitations_full_name_check CHECK (((full_name IS NULL) OR (char_length(full_name) <= 80)));
