-- 3. Functions
CREATE OR REPLACE FUNCTION public._active_ride_charge_preview(p_ride public.rides, p_pickup_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_total integer;
  v_w record;
BEGIN
  SELECT s.total INTO v_total FROM public.ride_pricing_snapshots s
   WHERE s.ride_id = p_ride.id AND s.snapshot_type = 'estimate' LIMIT 1;
  IF v_total IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_w FROM public._wait_charge_for(p_ride.service_type, p_ride.driver_arrived_at, p_pickup_at);
  RETURN jsonb_build_object(
    'agreed_cup', v_total,
    'discount_cup', COALESCE(p_ride.discount_amount_cup, 0),
    'wait_minutes', v_w.wait_minutes,
    'billable_minutes', v_w.billable_minutes,
    'wait_cup', v_w.charge,
    'insurance_cup', CASE WHEN p_ride.insurance_selected AND p_ride.insurance_premium_cup > 0
                          THEN p_ride.insurance_premium_cup ELSE 0 END,
    'is_corporate', p_ride.corporate_account_id IS NOT NULL,
    'total_cup', GREATEST(v_total - COALESCE(p_ride.discount_amount_cup, 0), 0) + v_w.charge);
END;
$function$
;
REVOKE ALL ON FUNCTION public._active_ride_charge_preview(public.rides,timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._active_ride_charge_preview(public.rides,timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION public._claim_reward(p_user_id uuid, p_claim text, p_ride_id uuid DEFAULT NULL::uuid, p_referral_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_hash text := public._reward_identity_hash(p_user_id);
  v_ok boolean;
BEGIN
  IF v_hash IS NULL THEN
    RETURN 'no_phone';
  END IF;

  INSERT INTO public.reward_claims (identity_hash, claim, user_id, ride_id, referral_id)
  VALUES (v_hash, p_claim, p_user_id, p_ride_id, p_referral_id)
  ON CONFLICT (identity_hash, claim) DO UPDATE
     SET user_id = EXCLUDED.user_id,
         ride_id = EXCLUDED.ride_id,
         referral_id = EXCLUDED.referral_id,
         claimed_at = now(),
         released_at = NULL
   WHERE public.reward_claims.released_at IS NOT NULL
  RETURNING true INTO v_ok;

  RETURN CASE WHEN v_ok THEN 'claimed' ELSE 'taken' END;
END;
$function$
;
REVOKE ALL ON FUNCTION public._claim_reward(uuid,text,uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._claim_reward(uuid,text,uuid,uuid) TO service_role;

