CREATE OR REPLACE FUNCTION public._poi_leading_venue_name(p_addr text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
  -- The venue part of a ride address: "Coppelia, Calle 23 e/ L y K, Plaza, La Habana" → "Coppelia".
  -- NULL for placeholders, corner / street forms, zone names, numeric or too-short text.
  SELECT CASE
    WHEN public._ride_address_is_placeholder(p_addr) THEN NULL
    WHEN v.lead IS NULL OR length(v.lead) < 3 OR length(v.lead) > 80 THEN NULL
    WHEN v.lead !~ '[[:alpha:]].*[[:alpha:]]' THEN NULL
    WHEN v.lead ~* '(^|\s)(e/|entre|esq\.?|esquina|y)(\s|$)' THEN NULL
    WHEN v.lead ~* '^(calle|calzada|avenida|ave\.?|av\.?|avda\.?|carretera|camino|callejon|callejón|paseo|linea|línea|km|kilometro|kilómetro|autopista|circunvalacion|circunvalación|reparto|rpto\.?|edificio|edif\.?|apto\.?|apartamento|cerca de)(\s|$)' THEN NULL
    WHEN v.lead ~ '^\d' THEN NULL
    WHEN lower(unaccent(v.lead)) IN (
      'vedado', 'el vedado', 'nuevo vedado', 'miramar', 'centro habana', 'habana vieja', 'la habana vieja', 'cerro',
      'playa', 'marianao', 'la lisa', 'boyeros', 'alamar', 'cojimar', 'santos suarez', 'lawton', 'luyano',
      'la vibora', 'vibora', 'siboney', 'kohly', 'casino deportivo', 'santa fe', 'guanabo', 'regla', 'guanabacoa',
      'la habana', 'habana', 'varadero', 'centro historico', 'reparto flores', 'buenavista', 'buena vista') THEN NULL
    WHEN EXISTS (SELECT 1 FROM public.cuba_admin_areas a
                 WHERE lower(unaccent(a.name)) = lower(unaccent(v.lead))
                    OR lower(unaccent(COALESCE(a.name_es, ''))) = lower(unaccent(v.lead))) THEN NULL
    ELSE v.lead END
  FROM (SELECT NULLIF(btrim(split_part(COALESCE(p_addr, ''), ',', 1)), '') AS lead) v;
$function$
;
REVOKE ALL ON FUNCTION public._poi_leading_venue_name(text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._poi_leading_venue_name(text) TO service_role;

CREATE OR REPLACE FUNCTION public._reward_identity_hash(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_digits text;
  v_salt text;
BEGIN
  SELECT regexp_replace(u.phone, '\D', '', 'g') INTO v_digits
    FROM auth.users u
   WHERE u.id = p_user_id
     AND u.phone_confirmed_at IS NOT NULL;
  IF v_digits IS NULL OR v_digits = '' THEN
    RETURN NULL;
  END IF;

  SELECT s.salt INTO v_salt FROM public.reward_identity_salt s WHERE s.id = 1;
  IF v_salt IS NULL OR v_salt = '' THEN
    RETURN NULL;
  END IF;

  RETURN encode(sha256(convert_to(v_salt || ':' || v_digits, 'UTF8')), 'hex');
END;
$function$
;
REVOKE ALL ON FUNCTION public._reward_identity_hash(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._reward_identity_hash(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public._ride_address_is_placeholder(p_addr text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
  SELECT
    p_addr IS NULL
    OR btrim(p_addr) = ''
    -- coordenadas crudas tipo "23.12638, -82.35472"
    OR p_addr ~ '^\s*-?\d{1,3}\.\d+\s*,\s*-?\d{1,3}\.\d+\s*$'
    -- fallback viejo del picker de mapa
    OR p_addr = 'Ubicación seleccionada en el mapa'
    -- fallback del cliente por preset local (el servidor lo mejora si puede)
    OR p_addr LIKE 'Cerca de %'
    -- 00546: textos provisionales de la UI (es / en / pt)
    OR btrim(p_addr) IN (
         'Detectando dirección...',
         'Detecting address...',
         'Detectando endereço...',
         'Origen',
         'Destino',
         'Mi ubicación'
       );
$function$
;
REVOKE ALL ON FUNCTION public._ride_address_is_placeholder(text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._ride_address_is_placeholder(text) TO service_role;

CREATE OR REPLACE FUNCTION public._ride_gps_departure_at(p_ride_id uuid, p_since timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE
  -- Measured in prod on 2026-10-12: a live app sends a point every few seconds
  -- while the driver waits, and the longest gap seen was 5.5 minutes. A silence
  -- longer than 6 minutes is treated as the app not running, and the wait it did
  -- not record is not charged.
  c_max_gap constant interval := interval '6 minutes';
  v_far timestamptz;
  v_last timestamptz;
BEGIN
  IF p_since IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT min(LEAST(le.recorded_at, le.received_at)) INTO v_far
  FROM public.ride_location_events le
  JOIN public.rides r ON r.id = le.ride_id
  WHERE le.ride_id = p_ride_id
    AND le.driver_id = r.driver_id
    AND LEAST(le.recorded_at, le.received_at) >= p_since
    AND ST_Distance(le.location, r.pickup_location) > 100;
  IF v_far IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT max(LEAST(le.recorded_at, le.received_at)) INTO v_last
  FROM public.ride_location_events le
  JOIN public.rides r ON r.id = le.ride_id
  WHERE le.ride_id = p_ride_id
    AND le.driver_id = r.driver_id
    AND LEAST(le.recorded_at, le.received_at) >= p_since
    AND LEAST(le.recorded_at, le.received_at) < v_far;
  v_last := COALESCE(v_last, p_since);
  IF v_far - v_last > c_max_gap THEN
    RETURN LEAST(v_last, now());
  END IF;
  RETURN LEAST(v_far, now());
END;
$function$
;
REVOKE ALL ON FUNCTION public._ride_gps_departure_at(uuid,timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._ride_gps_departure_at(uuid,timestamp with time zone) TO service_role;

