CREATE OR REPLACE FUNCTION public._support_alert(p_ride_id uuid, p_kind text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_ride     public.rides%ROWTYPE;
  v_admins   uuid[];
  v_key      text;
  v_code     text := public._ride_short_code(p_ride_id);
  v_link     text := 'https://admin.tricigo.com/rides/' || p_ride_id::text || '/assist';
  v_wait_min integer;
  v_title    text;
  v_body     text;
BEGIN
  SELECT * INTO v_ride FROM public.rides WHERE id = p_ride_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_key := public.get_service_role_key();
  IF v_key IS NULL OR v_key = '' THEN
    RAISE WARNING '_support_alert: no service role key, the % push for ride % was not sent', p_kind, p_ride_id;
    PERFORM public.log_rpc_attempt('_support_alert', auth.uid(), p_ride_id, 'alert_failed',
      jsonb_build_object('kind', p_kind, 'error', 'no service role key'));
    RETURN;
  END IF;

  v_wait_min := GREATEST(0, floor(extract(epoch FROM now() - GREATEST(v_ride.created_at, v_ride.scheduled_at)) / 60))::int;
  v_title := CASE WHEN p_kind = 'help' THEN 'Pasajero pide ayuda · ' ELSE 'Viaje sin conductor · ' END
             || public._ride_type_label(v_ride.service_type, v_ride.ride_mode) || ' · ' || v_code;
  v_body := 'Espera ' || v_wait_min || ' min · '
         || left(COALESCE(v_ride.pickup_address, '—'), 60) || ' → ' || left(COALESCE(v_ride.dropoff_address, '—'), 60);

  SELECT array_agg(u.id) INTO v_admins
  FROM public.users u
  WHERE u.role IN ('admin', 'super_admin') AND u.is_active;
  IF v_admins IS NOT NULL THEN
    PERFORM public.cron_http_post(
      CASE WHEN p_kind = 'help' THEN 'support-help-alert' ELSE 'support-wait-alert' END,
      url     := 'https://lqaufszburqvlslpcuac.supabase.co/functions/v1/send-push',
      headers := jsonb_build_object('Content-Type', 'application/json',
                                    'Authorization', 'Bearer ' || v_key, 'apikey', v_key),
      body    := jsonb_build_object(
        'user_ids', to_jsonb(v_admins),
        'title', v_title, 'body', v_body, 'category', 'system',
        'data', jsonb_build_object('event', 'support_' || p_kind, 'ride_id', p_ride_id::text, 'url', v_link)));
  END IF;
EXCEPTION WHEN OTHERS THEN
  -- An alert never fails its caller (the rider's button, the cron).
  RAISE WARNING '_support_alert failed for ride %: % %', p_ride_id, SQLSTATE, SQLERRM;
  PERFORM public.log_rpc_attempt('_support_alert', auth.uid(), p_ride_id, 'alert_failed',
    jsonb_build_object('kind', p_kind, 'error', SQLERRM));
END;
$function$
;
REVOKE ALL ON FUNCTION public._support_alert(uuid,text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._support_alert(uuid,text) TO service_role;

CREATE OR REPLACE FUNCTION public._team_cancel_pending_for(p_user uuid, p_by uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_count integer;
BEGIN
  UPDATE public.team_invitations i
     SET status = 'canceled', canceled_at = now(), canceled_by = p_by
   WHERE i.status = 'pending'
     AND (i.email = (SELECT lower(btrim(coalesce(u.email, ''))) FROM public.users u WHERE u.id = p_user)
          OR i.email IN (SELECT lower(btrim(coalesce(ai.identity_data->>'email', '')))
                         FROM auth.identities ai WHERE ai.user_id = p_user));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$
;
REVOKE ALL ON FUNCTION public._team_cancel_pending_for(uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._team_cancel_pending_for(uuid,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public._team_check_last_super_admin(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.role = 'super_admin' AND coalesce(u.is_active, true) AND u.id <> p_user
      AND u.id NOT IN ('00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000099')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'Tiene que quedar al menos un superadministrador.', DETAIL = 'team_last_super_admin';
  END IF;
END;
$function$
;
REVOKE ALL ON FUNCTION public._team_check_last_super_admin(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._team_check_last_super_admin(uuid) TO service_role;

