CREATE OR REPLACE FUNCTION public._team_write_role(p_user uuid, p_role public.user_role)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  PERFORM set_config('app.team_role_change', '1', true);
  UPDATE public.users SET role = p_role WHERE id = p_user;
  PERFORM set_config('app.team_role_change', '', true);
END;
$function$
;
REVOKE ALL ON FUNCTION public._team_write_role(uuid,public.user_role) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._team_write_role(uuid,public.user_role) TO service_role;

CREATE OR REPLACE FUNCTION public._third_party_person_name(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  WITH w AS (
    SELECT t.word, row_number() OVER (ORDER BY t.ord) AS n
    FROM (
      SELECT regexp_replace(s.word, '[^A-Za-zÀ-ÖØ-öø-ÿ''-]', '', 'g') AS word, s.ord
      FROM regexp_split_to_table(coalesce(p_name, ''), '\s+') WITH ORDINALITY AS s(word, ord)
    ) t
    WHERE t.word ~ '[A-Za-zÀ-ÖØ-öø-ÿ]'
  )
  SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM w WHERE n = 2) THEN (SELECT left(word, 20) FROM w WHERE n = 1)
    ELSE (SELECT left(word, 20) FROM w WHERE n = 1) || ' ' || (SELECT upper(left(word, 1)) FROM w WHERE n = 2) || '.'
  END;
$function$
;
REVOKE ALL ON FUNCTION public._third_party_person_name(text) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public._users_blocked(p_a uuid, p_b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_blocks ub
    WHERE (ub.blocker_id = p_a AND ub.blocked_id = p_b)
       OR (ub.blocker_id = p_b AND ub.blocked_id = p_a)
  )
$function$
;
REVOKE ALL ON FUNCTION public._users_blocked(uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._users_blocked(uuid,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public._vehicle_types_for_service(p_service_type text)
 RETURNS public.vehicle_type[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT CASE
    WHEN p_service_type LIKE 'triciclo%' THEN ARRAY['triciclo'::public.vehicle_type]
    WHEN p_service_type LIKE 'moto%'     THEN ARRAY['moto'::public.vehicle_type]
    WHEN p_service_type LIKE 'auto%'     THEN ARRAY['auto'::public.vehicle_type, 'confort'::public.vehicle_type]
    WHEN p_service_type = 'mensajeria'   THEN NULL
    ELSE ARRAY['triciclo'::public.vehicle_type]
  END
$function$
;
REVOKE ALL ON FUNCTION public._vehicle_types_for_service(text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._vehicle_types_for_service(text) TO service_role;

CREATE OR REPLACE FUNCTION public._wait_charge_for(p_service_type text, p_arrived_at timestamp with time zone, p_pickup_at timestamp with time zone, OUT wait_minutes integer, OUT billable_minutes integer, OUT charge integer)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_svc public.service_type_configs%ROWTYPE;
  v_wait_seconds numeric;
  v_max_billable integer;
  v_band_rate integer;
  v_at_t time;
  v_at_dow int;
BEGIN
  IF p_arrived_at IS NULL OR p_pickup_at IS NULL THEN
    wait_minutes := 0; billable_minutes := 0; charge := 0;
    RETURN;
  END IF;
  SELECT * INTO v_svc FROM public.service_type_configs WHERE slug = p_service_type;
  v_wait_seconds := EXTRACT(EPOCH FROM (p_pickup_at - p_arrived_at));
  wait_minutes := GREATEST(0, FLOOR(v_wait_seconds / 60)::integer);
  billable_minutes := GREATEST(0, wait_minutes - COALESCE(v_svc.free_wait_minutes, 5));
  v_max_billable := GREATEST(0, public.get_platform_config_numeric('max_billable_wait_minutes', 20)::integer);
  billable_minutes := LEAST(billable_minutes, v_max_billable);

  -- 00502: the rate of the band the wait STARTED in (Havana time).
  BEGIN
    v_at_t   := (p_arrived_at AT TIME ZONE 'America/Havana')::time;
    v_at_dow := EXTRACT(dow FROM (p_arrived_at AT TIME ZONE 'America/Havana'))::int;
    SELECT pr.per_wait_minute_rate_cup INTO v_band_rate
    FROM public.pricing_rules pr
    WHERE pr.service_type = p_service_type
      AND pr.is_active = true
      AND pr.per_wait_minute_rate_cup IS NOT NULL
      AND (pr.time_window_start IS NULL OR pr.time_window_end IS NULL OR
           CASE WHEN pr.time_window_start <= pr.time_window_end
                THEN v_at_t >= pr.time_window_start AND v_at_t < pr.time_window_end
                ELSE v_at_t >= pr.time_window_start OR v_at_t < pr.time_window_end END)
      AND (pr.day_of_week IS NULL OR array_length(pr.day_of_week, 1) IS NULL
           OR v_at_dow = ANY(pr.day_of_week))
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_band_rate := NULL;
  END;

  charge := billable_minutes * COALESCE(v_band_rate, v_svc.per_wait_minute_rate_cup, 0);
END;
$function$
;
REVOKE ALL ON FUNCTION public._wait_charge_for(text,timestamp with time zone,timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public._wait_charge_for(text,timestamp with time zone,timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION public.admin_active_ride_context(p_ride_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE
  v_ride public.rides%ROWTYPE;
  v_driver_user uuid;
  v_actions text[];
  v_dep timestamptz;
  v_start timestamptz;
  v_source text;
  v_preview jsonb;
  v_proof_missing boolean;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('error', 'forbidden');
  END IF;
  SELECT * INTO v_ride FROM public.rides WHERE id = p_ride_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'ride_not_found');
  END IF;
  SELECT dp.user_id INTO v_driver_user FROM public.driver_profiles dp WHERE dp.id = v_ride.driver_id;
  IF auth.uid() = v_ride.customer_id OR auth.uid() = v_driver_user THEN
    RETURN jsonb_build_object('error', 'self_ride');
  END IF;

  v_actions := CASE v_ride.status
    WHEN 'accepted' THEN ARRAY['release', 'advance']
    WHEN 'driver_en_route' THEN ARRAY['release', 'advance']
    WHEN 'arrived_at_pickup' THEN ARRAY['advance']
    WHEN 'in_progress' THEN ARRAY['advance', 'complete']
    WHEN 'arrived_at_destination' THEN ARRAY['complete']
    ELSE ARRAY[]::text[] END;
  -- Only what the RPCs accept: a ride scheduled for later is neither released
  -- nor advanced (support cancels it from the ride page).
  IF v_ride.status IN ('accepted', 'driver_en_route') AND v_ride.scheduled_at > now() THEN
    v_actions := array_remove(array_remove(v_actions, 'release'), 'advance');
  END IF;
  -- A cargo ride is completed only with the recipient's code and the delivery
  -- photo (admin_complete_active_ride refuses otherwise). The driver's app asks
  -- for them only while the ride is in_progress, so support does not move it to
  -- the destination either (admin_advance_active_ride refuses that step).
  v_proof_missing := COALESCE(v_ride.ride_mode::text = 'cargo', false) AND NOT EXISTS (
    SELECT 1 FROM public.delivery_details dd
    WHERE dd.ride_id = v_ride.id AND dd.delivery_otp_validated_at IS NOT NULL AND dd.delivery_photo_url IS NOT NULL);
  IF v_proof_missing THEN
    v_actions := array_remove(v_actions, 'complete');
    IF v_ride.status = 'in_progress' THEN
      v_actions := array_remove(v_actions, 'advance');
    END IF;
  END IF;

  IF v_ride.status = 'arrived_at_pickup' THEN
    v_dep := public._ride_gps_departure_at(v_ride.id, v_ride.driver_arrived_at);
    v_start := COALESCE(v_ride.pickup_at, v_dep, v_ride.driver_arrived_at, now());
    v_source := CASE WHEN v_ride.pickup_at IS NOT NULL THEN 'recorded'
                     WHEN v_dep IS NOT NULL THEN 'gps'
                     WHEN v_ride.driver_arrived_at IS NOT NULL THEN 'arrival'
                     ELSE 'now' END;
    v_preview := public._active_ride_charge_preview(v_ride, v_start);
  ELSIF v_ride.status IN ('in_progress', 'arrived_at_destination') THEN
    v_preview := public._active_ride_charge_preview(v_ride, v_ride.pickup_at);
  ELSE
    v_preview := public._active_ride_charge_preview(v_ride, NULL);
  END IF;

  RETURN jsonb_build_object(
    'ride', (SELECT jsonb_build_object(
        'id', v_ride.id, 'code', public._ride_short_code(v_ride.id), 'status', v_ride.status,
        'service_type', v_ride.service_type, 'payment_method', v_ride.payment_method,
        'is_corporate', v_ride.corporate_account_id IS NOT NULL,
        'pickup_address', v_ride.pickup_address, 'dropoff_address', v_ride.dropoff_address,
        'created_at', v_ride.created_at, 'accepted_at', v_ride.accepted_at,
        'driver_arrived_at', v_ride.driver_arrived_at, 'pickup_at', v_ride.pickup_at,
        'scheduled_at', v_ride.scheduled_at, 'estimated_fare_cup', v_ride.estimated_fare_cup,
        'customer_id', v_ride.customer_id, 'customer_name', c.full_name,
        'customer_phone', c.phone, 'customer_is_test', c.is_test)
      FROM public.users c WHERE c.id = v_ride.customer_id),
    'driver', (SELECT jsonb_build_object(
        'driver_profile_id', dp.id, 'full_name', u.full_name, 'phone', u.phone,
        'is_online', dp.is_online, 'last_heartbeat_at', dp.last_heartbeat_at,
        'vehicle_label', (SELECT concat_ws(' · ',
             NULLIF(concat_ws(' ', NULLIF(btrim(v.make), ''), NULLIF(btrim(v.model), '')), ''),
             NULLIF(btrim(v.color), ''), NULLIF(btrim(v.plate_number), ''))
           FROM public.vehicles v WHERE v.driver_id = dp.id AND v.is_active LIMIT 1))
      FROM public.driver_profiles dp JOIN public.users u ON u.id = dp.user_id
      WHERE dp.id = v_ride.driver_id),
    'last_point', (SELECT jsonb_build_object(
        'recorded_at', le.recorded_at, 'received_at', le.received_at,
        'distance_to_pickup_m', round(ST_Distance(le.location, v_ride.pickup_location))::int,
        'distance_to_dropoff_m', round(ST_Distance(le.location, v_ride.dropoff_location))::int)
      FROM public.ride_location_events le
      WHERE le.ride_id = v_ride.id AND le.driver_id = v_ride.driver_id
      ORDER BY GREATEST(le.recorded_at, le.received_at) DESC, le.recorded_at DESC, le.id DESC LIMIT 1),
    'alert', (SELECT jsonb_build_object('reason', a.reason, 'detected_at', a.detected_at)
      FROM public.stuck_ride_alerts a WHERE a.ride_id = v_ride.id AND a.resolved_at IS NULL),
    'driver_profile_id', v_ride.driver_id,
    'delivery_proof_missing', v_proof_missing,
    'preview', v_preview,
    'start_pickup_at', CASE WHEN v_ride.status = 'arrived_at_pickup' THEN v_start END,
    'start_pickup_source', v_source,
    'allowed_actions', to_jsonb(v_actions));
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_active_ride_context(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_active_ride_context(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_active_ride_context(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_adjust_wallet(p_target_user_id uuid, p_account_type public.wallet_account_type, p_amount_cup integer, p_reason text, p_admin_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_account_id UUID;
  v_new_balance INTEGER;
  v_tx_id UUID;
  v_is_admin BOOLEAN;
  v_metadata jsonb := '{}'::jsonb;
BEGIN
  IF auth.uid() <> p_admin_user_id THEN
    RAISE EXCEPTION 'Forbidden: p_admin_user_id must match caller';
  END IF;
  SELECT (role IN ('admin', 'super_admin')) INTO v_is_admin FROM users WHERE id = p_admin_user_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;
  IF p_target_user_id = p_admin_user_id THEN
    RAISE EXCEPTION 'Forbidden: an admin cannot adjust their own wallet';
  END IF;
  IF p_amount_cup = 0 THEN
    RAISE EXCEPTION 'Amount cannot be zero';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'Reason is required (min 3 chars)';
  END IF;

  IF p_account_type NOT IN ('customer_cash', 'driver_cash', 'corporate_cash', 'tricicoin') THEN
    RAISE EXCEPTION 'Unsupported account type: %', p_account_type;
  END IF;

  SELECT id INTO v_account_id FROM wallet_accounts
    WHERE user_id = p_target_user_id AND account_type = p_account_type LIMIT 1;
  IF v_account_id IS NULL THEN
    INSERT INTO wallet_accounts (user_id, account_type, balance, held_balance, currency, is_active)
    VALUES (
      p_target_user_id, p_account_type, 0, 0,
      CASE WHEN p_account_type = 'tricicoin' THEN 'TRC' ELSE 'CUP' END,
      true
    )
    RETURNING id INTO v_account_id;
  END IF;

  IF p_amount_cup > 0 AND p_account_type IN ('customer_cash', 'corporate_cash', 'tricicoin') THEN
    v_metadata := jsonb_build_object('anchor_directives', jsonb_build_array(
      jsonb_build_object('account_id', v_account_id, 'unbacked_cup_delta', p_amount_cup)
    ));
  END IF;

  INSERT INTO ledger_transactions (
    idempotency_key, type, status, reference_type, reference_id, description, metadata, created_by
  )
  VALUES (
    'admin_adjust:' || gen_random_uuid()::TEXT,
    'adjustment', 'posted', 'admin_action',
    p_admin_user_id, p_reason, v_metadata, p_admin_user_id
  )
  RETURNING id INTO v_tx_id;

  UPDATE wallet_accounts SET balance = balance + p_amount_cup, updated_at = NOW()
  WHERE id = v_account_id RETURNING balance INTO v_new_balance;

  INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
  VALUES (v_tx_id, v_account_id, p_amount_cup, v_new_balance);

  INSERT INTO admin_actions (admin_id, action, target_type, target_id, reason)
  VALUES (p_admin_user_id, 'adjust_wallet', 'wallet_account', v_account_id::TEXT, p_reason);

  RETURN jsonb_build_object(
    'transaction_id', v_tx_id,
    'account_id', v_account_id,
    'amount_cup', p_amount_cup,
    'new_balance', v_new_balance
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_adjust_wallet(uuid,public.wallet_account_type,integer,text,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_adjust_wallet(uuid,public.wallet_account_type,integer,text,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_adjust_wallet(uuid,public.wallet_account_type,integer,text,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.admin_get_online_fleet()
 RETURNS TABLE(driver_id uuid, user_id uuid, full_name text, phone text, status public.driver_status, is_online boolean, is_on_break boolean, last_heartbeat_at timestamp with time zone, lat double precision, lng double precision, current_heading integer, current_ride_id uuid, current_ride_status public.ride_status)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
#variable_conflict use_column
DECLARE
  v_is_admin BOOLEAN;
BEGIN
  -- Admin gate
  SELECT (role IN ('admin', 'super_admin')) INTO v_is_admin
  FROM users WHERE id = auth.uid();

  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  SELECT
    dp.id AS driver_id,
    dp.user_id,
    u.full_name,
    u.phone,
    dp.status,
    dp.is_online,
    dp.is_on_break,
    dp.last_heartbeat_at,
    ST_Y(dp.current_location::geometry) AS lat,
    ST_X(dp.current_location::geometry) AS lng,
    dp.current_heading::integer,
    r.id AS current_ride_id,
    r.status AS current_ride_status
  FROM driver_profiles dp
  JOIN users u ON u.id = dp.user_id
  LEFT JOIN LATERAL (
    SELECT rides.id, rides.status
    FROM rides
    WHERE rides.driver_id = dp.id
      AND rides.status IN ('accepted','driver_en_route','arrived_at_pickup','in_progress','arrived_at_destination')
    ORDER BY rides.created_at DESC
    LIMIT 1
  ) r ON true
  WHERE dp.is_online = true
    AND dp.status = 'approved'
    AND dp.current_location IS NOT NULL
  ORDER BY
    CASE
      WHEN r.status IN ('arrived_at_pickup','in_progress','arrived_at_destination') THEN 1
      WHEN r.status IN ('accepted','driver_en_route') THEN 2
      WHEN dp.is_on_break THEN 4
      ELSE 3
    END,
    u.full_name;
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_get_online_fleet() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_get_online_fleet() TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_get_online_fleet() TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_incomplete_driver_signups()
 RETURNS TABLE(driver_profile_id uuid, user_id uuid, full_name text, phone text, signed_up_at timestamp with time zone, last_sign_in_at timestamp with time zone, docs_uploaded integer, missing_docs text[], rejected_docs text[], has_push boolean, contact_count integer, last_contact_at timestamp with time zone, last_contact_by text, last_contact_channel text, last_contact_note text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'Admin only' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH req(doc_type, pos) AS (
    VALUES ('national_id', 1), ('selfie', 2), ('drivers_license', 3),
           ('vehicle_registration', 4), ('vehicle_photo', 5)
  ),
  base AS (
    SELECT dp.id, dp.user_id, u.full_name, u.phone, dp.created_at, au.last_sign_in_at
    FROM public.driver_profiles dp
    JOIN public.users u ON u.id = dp.user_id
    LEFT JOIN auth.users au ON au.id = dp.user_id
    WHERE dp.status = 'pending_verification'
      AND NOT coalesce(u.is_test, false)
  ),
  latest AS (
    SELECT DISTINCT ON (d.driver_id, d.document_type)
           d.driver_id, d.document_type::text AS doc_type, d.rejection_reason
    FROM public.driver_documents d
    WHERE d.driver_id IN (SELECT b.id FROM base b)
    ORDER BY d.driver_id, d.document_type, d.uploaded_at DESC NULLS LAST, d.id DESC
  ),
  contacts AS (
    SELECT DISTINCT ON (o.driver_profile_id)
           o.driver_profile_id, o.created_at, a.full_name AS by_name, o.channel, o.note,
           count(*) OVER (PARTITION BY o.driver_profile_id) AS n
    FROM public.driver_outreach_log o
    LEFT JOIN public.users a ON a.id = o.admin_id
    ORDER BY o.driver_profile_id, o.created_at DESC, o.id DESC
  )
  SELECT
    b.id,
    b.user_id,
    b.full_name,
    b.phone,
    b.created_at,
    b.last_sign_in_at,
    (SELECT count(*) FROM latest l JOIN req ON req.doc_type = l.doc_type
      WHERE l.driver_id = b.id AND l.rejection_reason IS NULL)::integer,
    coalesce((SELECT array_agg(req.doc_type ORDER BY req.pos) FROM req
      WHERE NOT EXISTS (SELECT 1 FROM latest l WHERE l.driver_id = b.id AND l.doc_type = req.doc_type)),
      '{}'::text[]),
    coalesce((SELECT array_agg(l.doc_type ORDER BY l.doc_type) FROM latest l
      WHERE l.driver_id = b.id AND l.rejection_reason IS NOT NULL), '{}'::text[]),
    EXISTS (SELECT 1 FROM public.user_devices ud WHERE ud.user_id = b.user_id),
    coalesce(c.n, 0)::integer,
    c.created_at,
    c.by_name,
    c.channel,
    c.note
  FROM base b
  LEFT JOIN contacts c ON c.driver_profile_id = b.id
  ORDER BY b.created_at DESC;
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_incomplete_driver_signups() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_incomplete_driver_signups() TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_incomplete_driver_signups() TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_invalidate_referral(p_referral_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_caller_is_admin BOOLEAN;
BEGIN
  -- BUG-131: caller must be admin/super_admin
  SELECT (role IN ('admin','super_admin'))
    INTO v_caller_is_admin
  FROM users WHERE id = auth.uid();
  IF NOT COALESCE(v_caller_is_admin, false) THEN
    RAISE EXCEPTION 'Forbidden: admin role required to invalidate referrals';
  END IF;

  UPDATE referrals
  SET status = 'invalidated'
  WHERE id = p_referral_id AND status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Referral not found or not pending: %', p_referral_id;
  END IF;
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_invalidate_referral(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_invalidate_referral(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_invalidate_referral(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.admin_launch_pulse(p_weeks integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_weeks integer := least(greatest(coalesce(p_weeks, 12), 1), 52);
  v_this_week date := date_trunc('week', now() AT TIME ZONE 'America/Havana')::date;
  v_first date := v_this_week - (v_weeks - 1) * 7;
  v_from timestamptz := v_first::timestamp AT TIME ZONE 'America/Havana';
  v_weeks_json jsonb;
  v_now_json jsonb;
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'Admin only' USING ERRCODE = '42501';
  END IF;

  WITH weeks AS (
    SELECT d::date AS week_start,
           d::timestamp AT TIME ZONE 'America/Havana' AS ts_from,
           (d::date + 7)::timestamp AT TIME ZONE 'America/Havana' AS ts_to
    FROM generate_series(v_first, v_this_week, interval '7 days') AS d
  ),
  real_users AS (
    SELECT u.id, u.created_at, u.signup_code, u.marketing_opt_in, u.marketing_opt_in_at,
           EXISTS (SELECT 1 FROM public.driver_profiles dp WHERE dp.user_id = u.id) AS is_driver,
           EXISTS (SELECT 1 FROM public.user_devices d WHERE d.user_id = u.id) AS has_push
    FROM public.users u
    WHERE NOT coalesce(u.is_test, false)
  ),
  ride_rows AS (
    SELECT r.id, r.customer_id, r.status::text AS status, r.created_at,
           (r.accepted_at IS NOT NULL OR r.driver_id IS NOT NULL) AS was_accepted,
           EXISTS (SELECT 1 FROM public.ride_offers o WHERE o.ride_id = r.id) AS had_offer
    FROM public.rides r
    JOIN public.users u ON u.id = r.customer_id
    WHERE NOT coalesce(u.is_test, false) AND r.created_at >= v_from
  ),
  rides_w AS (
    SELECT w.week_start,
      count(rr.id) AS requests,
      count(DISTINCT rr.customer_id) AS riders_requesting,
      count(rr.id) FILTER (WHERE rr.status = 'completed') AS completed,
      count(DISTINCT rr.customer_id) FILTER (WHERE rr.status = 'completed') AS riders_completed,
      count(rr.id) FILTER (WHERE rr.status = 'canceled' AND rr.was_accepted) AS accepted_canceled,
      count(rr.id) FILTER (WHERE rr.status = 'canceled' AND NOT rr.was_accepted AND rr.had_offer) AS offered_not_accepted,
      count(rr.id) FILTER (WHERE rr.status = 'canceled' AND NOT rr.was_accepted AND NOT rr.had_offer) AS no_offer,
      count(rr.id) FILTER (WHERE rr.status NOT IN ('completed', 'canceled')) AS open
    FROM weeks w
    LEFT JOIN ride_rows rr ON rr.created_at >= w.ts_from AND rr.created_at < w.ts_to
    GROUP BY w.week_start
  ),
  online_w AS (
    SELECT w.week_start,
      count(h.hour_start) AS hours_measured,
      round(avg(h.drivers_online), 2) AS online_avg,
      round(avg(h.drivers_online) FILTER (
        WHERE extract(hour FROM h.hour_start AT TIME ZONE 'America/Havana') BETWEEN 7 AND 20), 2) AS online_avg_day,
      round(avg(h.drivers_online) FILTER (
        WHERE extract(hour FROM h.hour_start AT TIME ZONE 'America/Havana') NOT BETWEEN 7 AND 20), 2) AS online_avg_night,
      round(100.0 * count(h.hour_start) FILTER (WHERE h.drivers_online = 0)
            / nullif(count(h.hour_start), 0), 1) AS hours_nobody_pct,
      (SELECT count(DISTINCT x) FROM public.driver_online_hourly h2, unnest(h2.driver_ids) AS x
        WHERE h2.hour_start >= w.ts_from AND h2.hour_start < w.ts_to) AS drivers_seen_online
    FROM weeks w
    LEFT JOIN public.driver_online_hourly h ON h.hour_start >= w.ts_from AND h.hour_start < w.ts_to
    GROUP BY w.week_start, w.ts_from, w.ts_to
  ),
  users_w AS (
    SELECT w.week_start,
      count(ru.id) FILTER (WHERE NOT ru.is_driver) AS rider_signups,
      count(ru.id) FILTER (WHERE ru.signup_code IS NOT NULL) AS coded_signups,
      count(ru.id) FILTER (WHERE ru.has_push) AS signups_with_push,
      count(ru.id) AS signups
    FROM weeks w
    LEFT JOIN real_users ru ON ru.created_at >= w.ts_from AND ru.created_at < w.ts_to
    GROUP BY w.week_start
  ),
  consent_w AS (
    SELECT w.week_start, count(ru.id) AS marketing_opt_ins
    FROM weeks w
    LEFT JOIN real_users ru ON ru.marketing_opt_in
      AND ru.marketing_opt_in_at >= w.ts_from AND ru.marketing_opt_in_at < w.ts_to
    GROUP BY w.week_start
  ),
  drivers_w AS (
    SELECT w.week_start,
      count(dp.id) FILTER (WHERE dp.created_at >= w.ts_from AND dp.created_at < w.ts_to) AS driver_signups,
      count(dp.id) FILTER (WHERE dp.approved_at >= w.ts_from AND dp.approved_at < w.ts_to) AS drivers_approved
    FROM weeks w
    LEFT JOIN (
      SELECT dp.id, dp.created_at, dp.approved_at
      FROM public.driver_profiles dp
      JOIN public.users u ON u.id = dp.user_id
      WHERE NOT coalesce(u.is_test, false)
    ) dp ON (dp.created_at >= w.ts_from AND dp.created_at < w.ts_to)
         OR (dp.approved_at >= w.ts_from AND dp.approved_at < w.ts_to)
    GROUP BY w.week_start
  ),
  referrals_w AS (
    SELECT w.week_start,
      count(rf.id) FILTER (WHERE rf.created_at >= w.ts_from AND rf.created_at < w.ts_to) AS referrals_created,
      count(rf.id) FILTER (WHERE rf.rewarded_at >= w.ts_from AND rf.rewarded_at < w.ts_to) AS referrals_rewarded
    FROM weeks w
    LEFT JOIN (
      SELECT rf.id, rf.created_at, rf.rewarded_at
      FROM public.referrals rf
      JOIN public.users u ON u.id = rf.referee_id
      WHERE NOT coalesce(u.is_test, false)
    ) rf ON (rf.created_at >= w.ts_from AND rf.created_at < w.ts_to)
         OR (rf.rewarded_at >= w.ts_from AND rf.rewarded_at < w.ts_to)
    GROUP BY w.week_start
  )
  SELECT jsonb_agg(jsonb_build_object(
      'week_start', w.week_start,
      'is_current', w.week_start = v_this_week,
      'requests', r.requests,
      'riders_requesting', r.riders_requesting,
      'completed', r.completed,
      'riders_completed', r.riders_completed,
      'accepted_canceled', r.accepted_canceled,
      'offered_not_accepted', r.offered_not_accepted,
      'no_offer', r.no_offer,
      'open', r.open,
      'hours_measured', o.hours_measured,
      'online_avg', o.online_avg,
      'online_avg_day', o.online_avg_day,
      'online_avg_night', o.online_avg_night,
      'hours_nobody_pct', o.hours_nobody_pct,
      'drivers_seen_online', o.drivers_seen_online,
      'signups', u.signups,
      'rider_signups', u.rider_signups,
      'driver_signups', d.driver_signups,
      'drivers_approved', d.drivers_approved,
      'coded_signups', u.coded_signups,
      'signups_with_push', u.signups_with_push,
      'marketing_opt_ins', c.marketing_opt_ins,
      'referrals_created', f.referrals_created,
      'referrals_rewarded', f.referrals_rewarded
    ) ORDER BY w.week_start DESC)
  INTO v_weeks_json
  FROM weeks w
  JOIN rides_w r USING (week_start)
  JOIN online_w o USING (week_start)
  JOIN users_w u USING (week_start)
  JOIN consent_w c USING (week_start)
  JOIN drivers_w d USING (week_start)
  JOIN referrals_w f USING (week_start);

  SELECT jsonb_build_object(
    'users', count(*),
    'users_with_push', count(*) FILTER (WHERE EXISTS (SELECT 1 FROM public.user_devices d WHERE d.user_id = u.id)),
    'users_opted_in', count(*) FILTER (WHERE u.marketing_opt_in),
    'drivers_approved', count(dp.id) FILTER (WHERE dp.status = 'approved'),
    'drivers_approved_with_push', count(dp.id) FILTER (WHERE dp.status = 'approved'
      AND EXISTS (SELECT 1 FROM public.user_devices d WHERE d.user_id = u.id)),
    'drivers_pending', count(dp.id) FILTER (WHERE dp.status = 'pending_verification'),
    'drivers_under_review', count(dp.id) FILTER (WHERE dp.status = 'under_review'),
    'drivers_online_now', count(dp.id) FILTER (WHERE dp.status = 'approved' AND dp.is_online)
  )
  INTO v_now_json
  FROM public.users u
  LEFT JOIN public.driver_profiles dp ON dp.user_id = u.id
  WHERE NOT coalesce(u.is_test, false);

  RETURN jsonb_build_object(
    'generated_at', now(),
    'timezone', 'America/Havana',
    'online_since', (SELECT min(hour_start) FROM public.driver_online_hourly),
    'now', v_now_json,
    'weeks', coalesce(v_weeks_json, '[]'::jsonb)
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_launch_pulse(integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_launch_pulse(integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_launch_pulse(integer) TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_reverse_gift(p_transfer_id uuid, p_admin_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_is_admin BOOLEAN;
  v_orig RECORD;
  v_recip_type wallet_account_type;
  v_sender_type wallet_account_type;
  v_recip_account_id UUID;
  v_sender_account_id UUID;
  v_recip_balance INTEGER;
  v_sender_balance INTEGER;
  v_recip_unbacked INTEGER;
  v_txn_id UUID;
  v_new_transfer_id UUID;
  v_rate numeric;
  v_unbacked_used INTEGER;
  v_backed_used INTEGER;
  v_backed_usd_cents numeric;
  v_metadata jsonb;
BEGIN
  IF auth.uid() <> p_admin_user_id THEN
    RAISE EXCEPTION 'Forbidden: p_admin_user_id must match caller';
  END IF;
  SELECT (role IN ('admin', 'super_admin')) INTO v_is_admin FROM users WHERE id = p_admin_user_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  SELECT * INTO v_orig FROM wallet_transfers WHERE id = p_transfer_id;
  IF v_orig.id IS NULL THEN
    RAISE EXCEPTION 'Gift not found';
  END IF;
  IF v_orig.reversed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Gift already reversed';
  END IF;
  IF v_orig.from_user_id IS NULL THEN
    RAISE EXCEPTION 'Cannot reverse a platform-originated gift; use admin_adjust_wallet instead';
  END IF;

  v_recip_type  := _gift_wallet_type(v_orig.to_user_id);
  v_sender_type := _gift_wallet_type(v_orig.from_user_id);
  PERFORM ensure_wallet_account(v_orig.to_user_id, v_recip_type);
  PERFORM ensure_wallet_account(v_orig.from_user_id, v_sender_type);

  SELECT id, balance, COALESCE(unbacked_cup, 0) INTO v_recip_account_id, v_recip_balance, v_recip_unbacked
    FROM wallet_accounts
    WHERE user_id = v_orig.to_user_id AND account_type = v_recip_type FOR UPDATE;
  IF v_recip_type <> 'customer_cash' AND v_recip_balance < v_orig.amount THEN
    RAISE EXCEPTION 'Cannot reverse: recipient already spent the gift (balance %, gift %)',
      v_recip_balance, v_orig.amount;
  END IF;

  SELECT id, balance INTO v_sender_account_id, v_sender_balance FROM wallet_accounts
    WHERE user_id = v_orig.from_user_id AND account_type = v_sender_type FOR UPDATE;

  v_rate := public.get_current_exchange_rate();
  v_unbacked_used := LEAST(v_recip_unbacked, v_orig.amount);
  v_backed_used := v_orig.amount - v_unbacked_used;
  v_backed_usd_cents := CASE WHEN v_rate > 0 THEN ROUND(v_backed_used / v_rate * 100) ELSE 0 END;
  v_metadata := jsonb_build_object('kind', 'gift_reversal', 'reversal_of', p_transfer_id, 'anchor_directives', jsonb_build_array(
    jsonb_build_object('account_id', v_recip_account_id,  'unbacked_cup_delta', -v_unbacked_used, 'anchor_usd_cents_delta', -v_backed_usd_cents),
    jsonb_build_object('account_id', v_sender_account_id, 'unbacked_cup_delta',  v_unbacked_used, 'anchor_usd_cents_delta',  v_backed_usd_cents)
  ));

  INSERT INTO ledger_transactions (
    idempotency_key, type, status, reference_type, reference_id, description, metadata, created_by
  )
  VALUES (
    'gift_reversal:' || p_transfer_id::TEXT, 'adjustment', 'posted', 'wallet_transfer',
    p_transfer_id, 'Reversión de regalo',
    v_metadata, p_admin_user_id
  )
  RETURNING id INTO v_txn_id;

  INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
    VALUES (v_txn_id, v_recip_account_id, -v_orig.amount, v_recip_balance - v_orig.amount);
  UPDATE wallet_accounts SET balance = v_recip_balance - v_orig.amount, updated_at = NOW()
    WHERE id = v_recip_account_id;

  INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
    VALUES (v_txn_id, v_sender_account_id, v_orig.amount, v_sender_balance + v_orig.amount);
  UPDATE wallet_accounts SET balance = v_sender_balance + v_orig.amount, updated_at = NOW()
    WHERE id = v_sender_account_id;

  INSERT INTO wallet_transfers (from_user_id, to_user_id, amount, note, transaction_id, kind, reversal_of)
    VALUES (v_orig.to_user_id, v_orig.from_user_id, v_orig.amount,
            'Reversión de regalo', v_txn_id, 'gift_reversal', p_transfer_id)
  RETURNING id INTO v_new_transfer_id;

  UPDATE wallet_transfers SET reversed_at = NOW(), reversed_by = p_admin_user_id
    WHERE id = p_transfer_id;

  INSERT INTO admin_actions (admin_id, action, target_type, target_id, reason)
    VALUES (p_admin_user_id, 'reverse_gift', 'wallet_transfer', p_transfer_id::TEXT, 'Reversión de regalo');

  RETURN v_new_transfer_id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_reverse_gift(uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_reverse_gift(uuid,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_reverse_gift(uuid,uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_reward_referral(p_referral_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_ref RECORD;
  v_exchange_rate NUMERIC;
  v_bonus_trc INTEGER;
  v_referrer_account_id UUID;
  v_platform_account_id UUID;
  v_referrer_balance INTEGER;
  v_platform_balance INTEGER;
  v_txn_id UUID;
  v_platform_user_id UUID := '00000000-0000-0000-0000-000000000001';
  v_caller_is_admin BOOLEAN;
  -- 00477: welcome bonus for the referee
  v_welcome_trc INTEGER;
  v_referee_account_id UUID;
  v_referee_balance INTEGER;
  v_welcome_txn_id UUID;
  v_claim TEXT;
BEGIN
  SELECT (role IN ('admin','super_admin'))
    INTO v_caller_is_admin
  FROM users WHERE id = auth.uid();
  IF NOT COALESCE(v_caller_is_admin, false) THEN
    RAISE EXCEPTION 'Forbidden: admin role required to reward referrals';
  END IF;

  SELECT * INTO v_ref
  FROM referrals WHERE id = p_referral_id AND status = 'pending'
  FOR UPDATE;

  IF v_ref IS NULL THEN
    RAISE EXCEPTION 'Referral not found or not pending: %', p_referral_id;
  END IF;

  -- 00658: one referral reward per confirmed phone. A referee without one
  -- can still be paid by an admin; a phone already paid for cannot.
  v_claim := public._claim_reward(v_ref.referee_id, 'referral_referee', NULL, v_ref.id);
  IF v_claim = 'taken' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'El teléfono de esta persona ya cobró un bono por referido.',
      DETAIL = 'referral_phone_already_rewarded';
  END IF;

  v_exchange_rate := get_current_exchange_rate();
  v_bonus_trc := cup_to_trc_centavos(GREATEST((CASE WHEN get_platform_config_numeric('referral_bonus_driver_cup', 0) > 0 AND EXISTS (SELECT 1 FROM driver_profiles WHERE user_id = v_ref.referee_id AND status = 'approved') THEN get_platform_config_numeric('referral_bonus_driver_cup', 0) ELSE get_platform_config_numeric('referral_bonus_cup', 500) END), 0)::integer, v_exchange_rate);

  -- 00394: credit the referrer's spendable TriciCoin (driver->tricicoin,
  -- passenger->customer_cash) instead of a hardcoded 'customer_cash'.
  v_referrer_account_id := ensure_wallet_account(v_ref.referrer_id, _gift_wallet_type(v_ref.referrer_id));
  v_platform_account_id := ensure_wallet_account(v_platform_user_id, 'platform_promotions');

  SELECT balance INTO v_platform_balance
    FROM wallet_accounts WHERE id = v_platform_account_id FOR UPDATE;
  SELECT balance INTO v_referrer_balance
    FROM wallet_accounts WHERE id = v_referrer_account_id FOR UPDATE;

  BEGIN
    INSERT INTO ledger_transactions (
      id, idempotency_key, type, status,
      reference_type, reference_id, description, created_by
    ) VALUES (
      gen_random_uuid(),
      'referral_bonus_admin:' || v_ref.id::TEXT,
      'promo_credit', 'posted',
      'referral', v_ref.id,
      'Bono de referido (admin) - codigo ' || v_ref.code,
      (SELECT auth.uid())
    )
    RETURNING id INTO v_txn_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE NOTICE 'Referral % already rewarded (idempotency_key collision)', p_referral_id;
    RETURN;
  END;

  INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
  VALUES (v_txn_id, v_platform_account_id, -v_bonus_trc, v_platform_balance - v_bonus_trc);

  INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
  VALUES (v_txn_id, v_referrer_account_id, v_bonus_trc, v_referrer_balance + v_bonus_trc);

  UPDATE wallet_accounts SET balance = balance - v_bonus_trc WHERE id = v_platform_account_id;
  UPDATE wallet_accounts SET balance = balance + v_bonus_trc WHERE id = v_referrer_account_id;

  UPDATE referrals
  SET status = 'rewarded', bonus_amount = v_bonus_trc, rewarded_at = NOW(), transaction_id = v_txn_id
  WHERE id = p_referral_id;

  -- 00477: optional welcome bonus for the REFEREE. Same shared idempotency
  -- key as the trigger paths, so a referral rewarded by trigger then retried
  -- by an admin can never pay the welcome bonus twice.
  v_welcome_trc := cup_to_trc_centavos(GREATEST((CASE WHEN get_platform_config_numeric('referral_welcome_bonus_driver_cup', 0) > 0 AND EXISTS (SELECT 1 FROM driver_profiles WHERE user_id = v_ref.referee_id AND status = 'approved') THEN get_platform_config_numeric('referral_welcome_bonus_driver_cup', 0) ELSE get_platform_config_numeric('referral_welcome_bonus_cup', 0) END), 0)::integer, v_exchange_rate);
  IF v_welcome_trc > 0 THEN
    v_referee_account_id := ensure_wallet_account(v_ref.referee_id, _gift_wallet_type(v_ref.referee_id));
    SELECT balance INTO v_referee_balance
      FROM wallet_accounts WHERE id = v_referee_account_id FOR UPDATE;
    SELECT balance INTO v_platform_balance
      FROM wallet_accounts WHERE id = v_platform_account_id;

    BEGIN
      INSERT INTO ledger_transactions (
        id, idempotency_key, type, status,
        reference_type, reference_id, description, created_by
      ) VALUES (
        gen_random_uuid(),
        'referral_welcome:' || v_ref.id::TEXT,
        'promo_credit', 'posted',
        'referral', v_ref.id,
        'Bono de bienvenida por referido - codigo ' || v_ref.code,
        v_ref.referee_id
      )
      RETURNING id INTO v_welcome_txn_id;

      INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
      VALUES (v_welcome_txn_id, v_platform_account_id, -v_welcome_trc, v_platform_balance - v_welcome_trc);

      INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
      VALUES (v_welcome_txn_id, v_referee_account_id, v_welcome_trc, v_referee_balance + v_welcome_trc);

      UPDATE wallet_accounts SET balance = balance - v_welcome_trc WHERE id = v_platform_account_id;
      UPDATE wallet_accounts SET balance = balance + v_welcome_trc WHERE id = v_referee_account_id;
    EXCEPTION WHEN unique_violation THEN
      RAISE NOTICE 'Welcome bonus for referral % already paid (idempotency)', p_referral_id;
    END;
  END IF;
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_reward_referral(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_reward_referral(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_reward_referral(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.admin_ride_assist_candidates(p_ride_id uuid, p_service_type text DEFAULT NULL::text)
 RETURNS TABLE(driver_profile_id uuid, full_name text, phone text, vehicle_type public.vehicle_type, vehicle_label text, is_online boolean, last_heartbeat_at timestamp with time zone, distance_m integer, busy_ride_id uuid, can_afford boolean, offer_status text, offer_expires_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
#variable_conflict use_column
DECLARE
  v_ride  public.rides%ROWTYPE;
  v_type  text;
  v_types public.vehicle_type[];
  v_cargo boolean;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_ride FROM public.rides WHERE id = p_ride_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  v_type  := COALESCE(p_service_type, v_ride.service_type);
  v_types := public._vehicle_types_for_service(v_type);
  v_cargo := (v_ride.ride_mode = 'cargo' OR v_type = 'mensajeria');

  RETURN QUERY
  SELECT dp.id,
         u.full_name,
         u.phone,
         v.type,
         -- A NULL or blank field drops out instead of blanking the whole label.
         concat_ws(' · ', NULLIF(concat_ws(' ', NULLIF(btrim(v.make), ''), NULLIF(btrim(v.model), '')), ''),
                   NULLIF(btrim(v.color), ''), NULLIF(btrim(v.plate_number), '')),
         dp.is_online,
         dp.last_heartbeat_at,
         ST_Distance(dp.current_location, v_ride.pickup_location)::int,
         (SELECT a.id FROM public.rides a
           WHERE a.driver_id = dp.id
             AND a.status IN ('accepted', 'driver_en_route', 'arrived_at_pickup', 'in_progress', 'arrived_at_destination')
           LIMIT 1),
         COALESCE((public.driver_can_afford_commission(dp.id, v_ride.estimated_fare_cup)->>'ok')::boolean, false),
         o.status,
         o.expires_at
  FROM public.driver_profiles dp
  JOIN public.users u ON u.id = dp.user_id
  JOIN LATERAL (
    SELECT v2.* FROM public.vehicles v2
    WHERE v2.driver_id = dp.id
      AND v2.is_active
      AND (v_types IS NULL OR v2.type = ANY (v_types))
      AND (NOT v_cargo OR v2.accepts_cargo IS TRUE)
    ORDER BY v2.created_at DESC
    LIMIT 1
  ) v ON true
  LEFT JOIN public.ride_offers o ON o.ride_id = v_ride.id AND o.driver_profile_id = dp.id
  WHERE dp.status = 'approved'
    AND u.is_active
    AND (dp.is_online OR dp.last_heartbeat_at > now() - interval '7 days')
    AND NOT public._users_blocked(v_ride.customer_id, dp.user_id)
  ORDER BY dp.is_online DESC, ST_Distance(dp.current_location, v_ride.pickup_location) ASC NULLS LAST, u.full_name
  LIMIT 60;
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_ride_assist_candidates(uuid,text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_ride_assist_candidates(uuid,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_ride_assist_candidates(uuid,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_ride_assist_context(p_ride_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_ride public.rides%ROWTYPE;
  v_out  jsonb;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('error', 'forbidden');
  END IF;
  SELECT * INTO v_ride FROM public.rides WHERE id = p_ride_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'ride_not_found');
  END IF;

  SELECT jsonb_build_object(
    'ride', jsonb_build_object(
      'id', v_ride.id, 'code', public._ride_short_code(v_ride.id), 'status', v_ride.status,
      'service_type', v_ride.service_type, 'ride_mode', v_ride.ride_mode,
      'estimated_fare_cup', v_ride.estimated_fare_cup, 'discount_amount_cup', v_ride.discount_amount_cup,
      'payment_method', v_ride.payment_method, 'passenger_count', v_ride.passenger_count,
      'shared_ride', COALESCE(v_ride.shared_ride, false),
      'is_corporate', v_ride.corporate_account_id IS NOT NULL,
      'has_waypoints', EXISTS (SELECT 1 FROM public.ride_waypoints w WHERE w.ride_id = v_ride.id),
      'pickup_address', v_ride.pickup_address, 'dropoff_address', v_ride.dropoff_address,
      'pickup_lat', v_ride.pickup_lat, 'pickup_lng', v_ride.pickup_lng,
      'dropoff_lat', v_ride.dropoff_lat, 'dropoff_lng', v_ride.dropoff_lng,
      'created_at', v_ride.created_at,
      'wait_s', GREATEST(0, floor(extract(epoch FROM now() - GREATEST(v_ride.created_at, v_ride.scheduled_at))))::int,
      'customer_id', v_ride.customer_id, 'customer_name', c.full_name,
      'customer_phone', c.phone, 'customer_is_test', c.is_test),
    'help_requested_at', ra.help_requested_at,
    'offers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'driver_profile_id', o.driver_profile_id, 'driver_name', du.full_name, 'status', o.status,
               'offered_at', o.offered_at, 'expires_at', o.expires_at, 'responded_at', o.responded_at)
             ORDER BY o.offered_at DESC)
      FROM public.ride_offers o
      JOIN public.driver_profiles dp ON dp.id = o.driver_profile_id
      JOIN public.users du ON du.id = dp.user_id
      WHERE o.ride_id = v_ride.id), '[]'::jsonb),
    'proposal', (
      SELECT jsonb_build_object(
               'id', p.id, 'from_service_type', p.from_service_type, 'to_service_type', p.to_service_type,
               'from_fare_cup', p.from_fare_cup, 'to_fare_cup', p.to_fare_cup, 'status', p.status,
               'expires_at', p.expires_at, 'responded_at', p.responded_at, 'created_at', p.created_at)
      FROM public.ride_service_proposals p
      WHERE p.ride_id = v_ride.id
      ORDER BY p.created_at DESC
      LIMIT 1))
  INTO v_out
  FROM public.users c
  LEFT JOIN public.ride_assist ra ON ra.ride_id = v_ride.id
  WHERE c.id = v_ride.customer_id;

  RETURN v_out;
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_ride_assist_context(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_ride_assist_context(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_ride_assist_context(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_send_gift(p_to_user_id uuid, p_amount integer, p_note text, p_admin_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_is_admin BOOLEAN;
  v_to_type  wallet_account_type;
  v_to_account_id UUID;
  v_new_balance INTEGER;
  v_to_active BOOLEAN;
  v_txn_id UUID;
  v_transfer_id UUID;
  v_platform_account_id UUID;
  v_platform_balance INTEGER;
BEGIN
  IF auth.uid() <> p_admin_user_id THEN
    RAISE EXCEPTION 'Forbidden: p_admin_user_id must match caller';
  END IF;
  SELECT (role IN ('admin', 'super_admin')) INTO v_is_admin FROM users WHERE id = p_admin_user_id;
  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;
  -- 00631: like admin_adjust_wallet, never the admin's own wallet.
  IF p_to_user_id = p_admin_user_id THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'No puedes enviarte un regalo a ti mismo.',
      DETAIL = 'gift_to_self';
  END IF;
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Gift amount must be positive';
  END IF;
  IF p_note IS NULL OR length(trim(p_note)) < 3 THEN
    RAISE EXCEPTION 'Reason/note is required (min 3 chars)';
  END IF;
  SELECT is_active INTO v_to_active FROM users WHERE id = p_to_user_id;
  IF NOT COALESCE(v_to_active, false) THEN
    RAISE EXCEPTION 'Recipient not found or inactive';
  END IF;

  v_to_type := _gift_wallet_type(p_to_user_id);
  PERFORM ensure_wallet_account(p_to_user_id, v_to_type);

  v_platform_account_id := ensure_wallet_account('00000000-0000-0000-0000-000000000001', 'platform_promotions');
  SELECT balance INTO v_platform_balance FROM wallet_accounts WHERE id = v_platform_account_id FOR UPDATE;

  INSERT INTO ledger_transactions (
    idempotency_key, type, status, reference_type, reference_id, description, metadata, created_by
  )
  VALUES (
    'admin_gift:' || gen_random_uuid()::TEXT, 'promo_credit', 'posted', 'admin_action',
    p_admin_user_id, p_note, jsonb_build_object('kind', 'gift', 'admin', true), p_admin_user_id
  )
  RETURNING id INTO v_txn_id;

  UPDATE wallet_accounts SET balance = balance - p_amount, updated_at = NOW() WHERE id = v_platform_account_id;
  INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
    VALUES (v_txn_id, v_platform_account_id, -p_amount, v_platform_balance - p_amount);

  UPDATE wallet_accounts SET balance = balance + p_amount, updated_at = NOW()
    WHERE user_id = p_to_user_id AND account_type = v_to_type
  RETURNING id, balance INTO v_to_account_id, v_new_balance;

  INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
    VALUES (v_txn_id, v_to_account_id, p_amount, v_new_balance);

  INSERT INTO wallet_transfers (from_user_id, to_user_id, amount, note, transaction_id, kind)
    VALUES (NULL, p_to_user_id, p_amount, p_note, v_txn_id, 'gift')
  RETURNING id INTO v_transfer_id;

  INSERT INTO admin_actions (admin_id, action, target_type, target_id, reason)
    VALUES (p_admin_user_id, 'send_gift', 'user', p_to_user_id::TEXT, p_note);

  RETURN v_transfer_id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_send_gift(uuid,integer,text,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_send_gift(uuid,integer,text,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_send_gift(uuid,integer,text,uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_set_user_active(p_user_id uuid, p_active boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_caller   uuid := auth.uid();
  v_role     public.user_role;
  v_reason   text := nullif(btrim(coalesce(p_reason, '')), '');
  v_sessions integer := 0;
BEGIN
  IF v_caller IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'Solo un administrador puede bloquear o desbloquear cuentas.', DETAIL = 'not_admin';
  END IF;
  IF p_user_id IS NULL OR p_active IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'Faltan datos para cambiar el estado de la cuenta.', DETAIL = 'missing_argument';
  END IF;
  IF p_user_id = v_caller THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'No puedes bloquear tu propia cuenta.', DETAIL = 'self';
  END IF;
  -- ...0001 owns the platform wallets and ...0099 the anonymized rows; 00604
  -- banned both until 2999. Unblocking either would lift that ban.
  IF p_user_id IN ('00000000-0000-0000-0000-000000000001'::uuid, '00000000-0000-0000-0000-000000000099'::uuid) THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'Las cuentas del sistema no se pueden bloquear ni desbloquear.', DETAIL = 'system_account';
  END IF;

  SELECT u.role INTO v_role FROM public.users u WHERE u.id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002',
      MESSAGE = 'La cuenta no existe.', DETAIL = 'not_found';
  END IF;
  IF v_role IN ('admin', 'super_admin') AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'Solo un super admin puede bloquear o desbloquear a otro administrador.', DETAIL = 'target_is_staff';
  END IF;
  IF NOT p_active AND v_reason IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'Escribe el motivo del bloqueo.', DETAIL = 'reason_required';
  END IF;

  IF p_active THEN
    UPDATE public.users SET is_active = true WHERE id = p_user_id;
    UPDATE auth.users SET banned_until = NULL WHERE id = p_user_id;
  ELSE
    UPDATE public.users SET is_active = false WHERE id = p_user_id;
    -- GoTrue refuses the login and the token refresh of a banned user. 100
    -- years is what GoTrue itself stores for its longest ban ('876000h').
    UPDATE auth.users SET banned_until = now() + interval '100 years' WHERE id = p_user_id;
    WITH s AS (DELETE FROM auth.sessions WHERE user_id = p_user_id RETURNING 1)
    SELECT count(*) INTO v_sessions FROM s;
    -- Refresh tokens with a session went with it (ON DELETE CASCADE); these
    -- are the ones without one.
    DELETE FROM auth.refresh_tokens WHERE user_id = p_user_id::text;
    UPDATE public.driver_profiles SET is_online = false, auto_offline_at = NULL
    WHERE user_id = p_user_id AND (is_online OR auto_offline_at IS NOT NULL);
  END IF;

  INSERT INTO public.admin_actions (admin_id, action, target_type, target_id, reason)
  VALUES (v_caller, CASE WHEN p_active THEN 'unblock_user' ELSE 'block_user' END,
          'user', p_user_id::text, v_reason);

  RETURN jsonb_build_object('user_id', p_user_id, 'is_active', p_active, 'sessions_closed', v_sessions);
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_set_user_active(uuid,boolean,text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_set_user_active(uuid,boolean,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_set_user_active(uuid,boolean,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_set_user_level(p_user_id uuid, p_level public.user_level)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_old    public.user_level;
BEGIN
  IF v_caller IS NULL OR NOT public.is_super_admin() THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'Solo un super admin puede cambiar el nivel de una cuenta.', DETAIL = 'not_super_admin';
  END IF;
  IF p_user_id IS NULL OR p_level IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'Faltan datos para cambiar el nivel.', DETAIL = 'missing_argument';
  END IF;

  SELECT u.level INTO v_old FROM public.users u WHERE u.id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002',
      MESSAGE = 'La cuenta no existe.', DETAIL = 'not_found';
  END IF;

  UPDATE public.users SET level = p_level WHERE id = p_user_id;

  INSERT INTO public.admin_actions (admin_id, action, target_type, target_id, reason)
  VALUES (v_caller, 'set_user_level', 'user', p_user_id::text, v_old::text || ' → ' || p_level::text);

  RETURN jsonb_build_object('user_id', p_user_id, 'level', p_level, 'previous_level', v_old);
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_set_user_level(uuid,public.user_level) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_set_user_level(uuid,public.user_level) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_set_user_level(uuid,public.user_level) TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_support_waiting_rides()
 RETURNS TABLE(ride_id uuid, code text, waiting_since timestamp with time zone, wait_s integer, help_requested_at timestamp with time zone, service_type text, estimated_fare_cup integer, pickup_address text, dropoff_address text, pending_offers integer, is_test boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
#variable_conflict use_column
DECLARE
  v_after integer := GREATEST(15, public.get_platform_config_numeric('support_alert_after_s', 60)::int);
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT r.id,
         public._ride_short_code(r.id),
         GREATEST(r.created_at, r.scheduled_at),
         GREATEST(0, floor(extract(epoch FROM now() - GREATEST(r.created_at, r.scheduled_at))))::int,
         ra.help_requested_at,
         r.service_type,
         r.estimated_fare_cup,
         r.pickup_address,
         r.dropoff_address,
         (SELECT count(*)::int FROM public.ride_offers o
           WHERE o.ride_id = r.id AND o.status = 'pending' AND o.expires_at > now()),
         c.is_test
  FROM public.rides r
  JOIN public.users c ON c.id = r.customer_id
  LEFT JOIN public.ride_assist ra ON ra.ride_id = r.id
  WHERE r.status = 'searching'
    AND GREATEST(r.created_at, r.scheduled_at) <= now()
    AND (ra.help_requested_at IS NOT NULL
         OR GREATEST(r.created_at, r.scheduled_at) <= now() - make_interval(secs => v_after))
  ORDER BY (ra.help_requested_at IS NULL), GREATEST(r.created_at, r.scheduled_at)
  LIMIT 50;
END;
$function$
;
REVOKE ALL ON FUNCTION public.admin_support_waiting_rides() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_support_waiting_rides() TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_support_waiting_rides() TO authenticated;

CREATE OR REPLACE FUNCTION public.apply_user_rating(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_role text;
  v_avg  numeric;
BEGIN
  PERFORM set_config('app.trusted_driver_update', '1', true);
  SELECT role::text INTO v_role FROM users WHERE id = p_user_id;
  v_avg := recompute_user_rating(p_user_id);
  IF v_role = 'driver' THEN
    UPDATE driver_profiles SET rating_avg = v_avg WHERE user_id = p_user_id;
  ELSIF v_role IN ('customer', 'super_admin', 'admin', 'marketing') THEN
    UPDATE customer_profiles SET rating_avg = v_avg WHERE user_id = p_user_id;
  END IF;
END;
$function$
;
REVOKE ALL ON FUNCTION public.apply_user_rating(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.apply_user_rating(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.approve_wallet_recharge(p_request_id uuid, p_admin_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_req RECORD; v_account_id UUID; v_current_balance INTEGER;
  v_txn_id UUID; v_idempotency_key TEXT;
BEGIN
  IF auth.uid() <> p_admin_id OR NOT is_admin() THEN
    RAISE EXCEPTION 'Forbidden: admin role required (and p_admin_id must match caller)';
  END IF;

  SELECT * INTO v_req FROM wallet_recharge_requests WHERE id = p_request_id FOR UPDATE;
  IF v_req IS NULL THEN RAISE EXCEPTION 'Recharge request not found: %', p_request_id; END IF;
  IF v_req.status <> 'pending' THEN
    RAISE EXCEPTION 'Recharge request % is not pending (status: %)', p_request_id, v_req.status;
  END IF;
  IF v_req.amount <= 0 THEN RAISE EXCEPTION 'Recharge amount must be positive, got %', v_req.amount; END IF;
  -- 00627: an admin cannot approve a recharge into their own wallet.
  IF v_req.user_id = p_admin_id THEN
    RAISE EXCEPTION 'Forbidden: an admin cannot approve their own recharge request'
      USING ERRCODE = '42501';
  END IF;

  v_idempotency_key := 'recharge:' || p_request_id::TEXT;
  SELECT id INTO v_txn_id FROM ledger_transactions WHERE idempotency_key = v_idempotency_key;
  IF v_txn_id IS NOT NULL THEN
    UPDATE wallet_recharge_requests SET status='approved', processed_by=p_admin_id,
           processed_at=COALESCE(processed_at, NOW())
    WHERE id = p_request_id;
    RETURN v_txn_id;
  END IF;

  v_account_id := ensure_wallet_account(v_req.user_id, 'customer_cash');
  SELECT balance INTO v_current_balance FROM wallet_accounts WHERE id = v_account_id FOR UPDATE;

  INSERT INTO ledger_transactions (idempotency_key, type, status, reference_type, reference_id, description, created_by)
  VALUES (v_idempotency_key, 'recharge', 'posted', 'recharge_request', p_request_id,
          'Recarga wallet #' || LEFT(p_request_id::TEXT, 8), p_admin_id)
  RETURNING id INTO v_txn_id;
  INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
  VALUES (v_txn_id, v_account_id, v_req.amount, v_current_balance + v_req.amount);
  UPDATE wallet_accounts SET balance = v_current_balance + v_req.amount, updated_at = NOW()
  WHERE id = v_account_id;
  UPDATE wallet_recharge_requests SET status='approved', processed_by=p_admin_id, processed_at=NOW()
  WHERE id = p_request_id;
  RETURN v_txn_id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.approve_wallet_recharge(uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.approve_wallet_recharge(uuid,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.approve_wallet_recharge(uuid,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.can_review_ride(p_ride_id uuid, p_reviewer_id uuid, p_reviewee_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.rides r
    LEFT JOIN public.driver_profiles dp ON dp.id = r.driver_id
    WHERE r.id = p_ride_id
      AND r.status = 'completed'::ride_status
      AND (
        (r.customer_id = p_reviewer_id AND dp.user_id = p_reviewee_id)
        OR
        (dp.user_id = p_reviewer_id AND r.customer_id = p_reviewee_id)
      )
  );
$function$
;
REVOKE ALL ON FUNCTION public.can_review_ride(uuid,uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.can_review_ride(uuid,uuid,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.can_review_ride(uuid,uuid,uuid) TO authenticated;

