CREATE OR REPLACE FUNCTION public.driver_can_afford_commission(p_driver_id uuid, p_estimated_fare_cup integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_user_id              uuid;
  v_balance_cup          integer;
  v_commission_rate      numeric;
  v_required_cup         integer;
BEGIN
  SELECT user_id INTO v_user_id FROM driver_profiles WHERE id = p_driver_id;
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'driver_not_found');
  END IF;

  SELECT COALESCE(balance, 0) INTO v_balance_cup
  FROM wallet_accounts
  WHERE user_id = v_user_id
    AND account_type = 'tricicoin';
  v_balance_cup := COALESCE(v_balance_cup, 0);

  SELECT (value #>> '{}')::NUMERIC INTO v_commission_rate
  FROM platform_config WHERE key = 'commission_rate';
  v_commission_rate := COALESCE(v_commission_rate, 0.15);

  v_required_cup := CEIL(COALESCE(p_estimated_fare_cup, 0)::numeric * v_commission_rate)::int;

  RETURN jsonb_build_object(
    'ok',              v_balance_cup >= v_required_cup,
    'balance_trc',     v_balance_cup,
    'required_trc',    v_required_cup,
    'balance_cup',     v_balance_cup,
    'required_cup',    v_required_cup,
    'commission_rate', v_commission_rate,
    'wallet_type',     'tricicoin'
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.driver_can_afford_commission(uuid,integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.driver_can_afford_commission(uuid,integer) TO service_role;

CREATE OR REPLACE FUNCTION public.enforce_ride_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_user_role user_role;
  v_transition_valid BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN
    INSERT INTO ride_transitions (ride_id, from_status, to_status, actor_id, actor_role)
    VALUES (NEW.id, OLD.status, NEW.status, NULL, 'admin');
    RETURN NEW;
  END IF;

  SELECT role INTO v_user_role FROM users WHERE id = auth.uid();

  -- Marketing rides as a passenger: its rights over a ride are a customer's
  -- (or a driver's, below, when it owns the approved driver profile).
  IF v_user_role = 'marketing' THEN
    v_user_role := 'customer';
  END IF;

  IF v_user_role NOT IN ('admin', 'super_admin')
     AND NEW.driver_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM driver_profiles dp
       WHERE dp.id = NEW.driver_id
         AND dp.user_id = auth.uid()
         AND dp.status = 'approved'
     ) THEN
    v_user_role := 'driver';
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM valid_transitions
    WHERE from_status = OLD.status
      AND to_status = NEW.status
      AND v_user_role = ANY(allowed_roles)
  ) INTO v_transition_valid;

  IF NOT v_transition_valid THEN
    RAISE EXCEPTION 'Invalid ride transition from % to % for role %',
      OLD.status, NEW.status, v_user_role;
  END IF;

  INSERT INTO ride_transitions (ride_id, from_status, to_status, actor_id, actor_role)
  VALUES (NEW.id, OLD.status, NEW.status, auth.uid(), v_user_role);

  NEW.updated_at := NOW();
  RETURN NEW;
END;
$function$
;
REVOKE ALL ON FUNCTION public.enforce_ride_transition() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.enforce_ride_transition() TO service_role;

CREATE OR REPLACE FUNCTION public.ensure_driver_role_and_tricicoin_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
BEGIN
  IF NEW.status = 'approved'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'approved') THEN
    -- Promote ONLY plain customers; leave admin/super_admin alone.
    -- Their elevated role takes precedence over the driver flag —
    -- the effective_role logic in 00143 already treats them as
    -- driver for ride transitions when they own the driver_profile.
    UPDATE users
       SET role = 'driver'
     WHERE id = NEW.user_id
       AND role NOT IN ('driver', 'admin', 'super_admin', 'marketing');

    -- Wallet provisioning is safe for any role (admins testing
    -- as drivers still need a tricicoin wallet to accept rides).
    INSERT INTO wallet_accounts (user_id, account_type, balance)
    VALUES (NEW.user_id, 'tricicoin'::wallet_account_type, 0)
    ON CONFLICT (user_id, account_type) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$function$
;
REVOKE ALL ON FUNCTION public.ensure_driver_role_and_tricicoin_on_approval() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ensure_driver_role_and_tricicoin_on_approval() TO service_role;

CREATE OR REPLACE FUNCTION public.ensure_wallet_account(p_user_id uuid, p_type public.wallet_account_type DEFAULT 'customer_cash'::public.wallet_account_type)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_id  UUID;
  v_uid UUID;
  v_ctx TEXT;
BEGIN
  -- 00591: a DIRECT call (PostgREST RPC from a signed-in, non-admin user)
  -- may only create the caller's own spendable accounts. Internal callers
  -- (send_gift, complete_ride_and_pay, admin_send_gift, the referral and
  -- corporate triggers, ...) are PL/pgSQL functions, so for them PG_CONTEXT
  -- carries at least one more frame below this one; a direct call has
  -- exactly one frame and therefore no newline. Service-role/cron callers
  -- have auth.uid() IS NULL and admins are exempt.
  v_uid := auth.uid();
  IF v_uid IS NOT NULL THEN
    GET DIAGNOSTICS v_ctx = PG_CONTEXT;
    IF position(E'\n' IN v_ctx) = 0 AND NOT is_admin() THEN
      IF p_user_id IS DISTINCT FROM v_uid
         OR p_type NOT IN ('customer_cash', 'tricicoin', 'corporate_cash') THEN
        RAISE EXCEPTION 'forbidden: ensure_wallet_account may only create your own customer_cash, tricicoin or corporate_cash account'
          USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;

  SELECT id INTO v_id FROM wallet_accounts WHERE user_id = p_user_id AND account_type = p_type;
  IF v_id IS NULL THEN
    INSERT INTO wallet_accounts (id, user_id, account_type, balance, held_balance, currency, anchor_usd_cents)
    VALUES (gen_random_uuid(), p_user_id, p_type, 0, 0, 'TRC',
            CASE WHEN p_type IN ('customer_cash', 'corporate_cash', 'tricicoin') THEN 0 ELSE NULL END)
    ON CONFLICT (user_id, account_type) DO NOTHING
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      SELECT id INTO v_id FROM wallet_accounts WHERE user_id = p_user_id AND account_type = p_type;
    END IF;
  END IF;
  RETURN v_id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.ensure_wallet_account(uuid,public.wallet_account_type) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ensure_wallet_account(uuid,public.wallet_account_type) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ensure_wallet_account(uuid,public.wallet_account_type) TO service_role;

CREATE OR REPLACE FUNCTION public.freeze_wallet(p_user_id uuid, p_reason text, p_admin_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF auth.uid() <> p_admin_id OR NOT is_admin() THEN
    RAISE EXCEPTION 'Forbidden: admin role required (and p_admin_id must match caller)';
  END IF;

  UPDATE wallet_accounts
  SET is_frozen = true, frozen_reason = p_reason,
      frozen_at = NOW(), frozen_by = p_admin_id
  WHERE user_id = p_user_id;

  INSERT INTO admin_actions (admin_id, action, target_type, target_id, reason)
  VALUES (p_admin_id, 'freeze_wallet', 'user', p_user_id::text, p_reason);
  RETURN true;
END;
$function$
;
REVOKE ALL ON FUNCTION public.freeze_wallet(uuid,text,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.freeze_wallet(uuid,text,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.freeze_wallet(uuid,text,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.get_admin_dashboard_metrics()
 RETURNS TABLE(active_rides bigint, total_rides_today bigint, online_drivers bigint, total_revenue_today bigint, pending_verifications bigint, open_incidents bigint, searching_rides bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'America/Havana')::date;
  v_day_start timestamptz := (v_today::timestamp AT TIME ZONE 'America/Havana');
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'forbidden: admin only' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT
    (SELECT COUNT(*) FROM rides
     WHERE status IN ('searching','accepted','driver_en_route','arrived_at_pickup','in_progress'))
      AS active_rides,
    (SELECT COUNT(*) FROM rides
     WHERE created_at >= v_day_start)
      AS total_rides_today,
    (SELECT COUNT(*) FROM driver_profiles
     WHERE is_online = true)
      AS online_drivers,
    (SELECT COALESCE(SUM(final_fare_cup), 0) FROM rides
     WHERE status = 'completed' AND completed_at >= v_day_start)
      AS total_revenue_today,
    (SELECT COUNT(*) FROM driver_profiles
     WHERE status IN ('pending_verification','under_review'))
      AS pending_verifications,
    (SELECT COUNT(*) FROM incident_reports
     WHERE status IN ('open','investigating'))
      AS open_incidents,
    (SELECT COUNT(*) FROM rides
     WHERE status = 'searching')
      AS searching_rides;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_admin_dashboard_metrics() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_admin_dashboard_metrics() TO PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_admin_dashboard_metrics() TO service_role;
GRANT EXECUTE ON FUNCTION public.get_admin_dashboard_metrics() TO authenticated;

