GRANT EXECUTE ON FUNCTION public.get_admin_wallet_stats() TO service_role;

CREATE OR REPLACE FUNCTION public.get_corporate_balance(p_account_id uuid)
 RETURNS TABLE(available integer, held integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'get_corporate_balance needs a signed-in user';
  END IF;
  IF NOT (public.is_admin() OR public.is_corp_admin(p_account_id)) THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'Solo un administrador de la empresa puede ver su saldo.',
      DETAIL = 'not_corporate_admin';
  END IF;

  -- The company's money is its creator's corporate_cash wallet.
  RETURN QUERY
    SELECT coalesce(w.balance, 0), coalesce(w.held_balance, 0)
    FROM public.corporate_accounts ca
    LEFT JOIN public.wallet_accounts w
      ON w.user_id = ca.created_by AND w.account_type = 'corporate_cash'
    WHERE ca.id = p_account_id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_corporate_balance(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_corporate_balance(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_corporate_balance(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_corporate_employees(p_account_id uuid)
 RETURNS TABLE(id uuid, corporate_account_id uuid, user_id uuid, role text, is_active boolean, added_by uuid, created_at timestamp with time zone, full_name text, phone text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'get_corporate_employees needs a signed-in user';
  END IF;
  IF NOT (public.is_admin() OR public.is_corp_admin(p_account_id)) THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'Solo un administrador de la empresa puede ver sus empleados.',
      DETAIL = 'not_corporate_admin';
  END IF;

  RETURN QUERY
    SELECT ce.id, ce.corporate_account_id, ce.user_id, ce.role, ce.is_active,
           ce.added_by, ce.created_at, u.full_name, u.phone
    FROM public.corporate_employees ce
    LEFT JOIN public.users u ON u.id = ce.user_id
    WHERE ce.corporate_account_id = p_account_id
    ORDER BY ce.created_at DESC, ce.id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_corporate_employees(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_corporate_employees(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_corporate_employees(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_current_exchange_rate()
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE v_rate NUMERIC;
BEGIN
  SELECT usd_cup_rate INTO v_rate FROM exchange_rates WHERE is_current = true LIMIT 1;
  IF v_rate IS NULL THEN
    SELECT usd_cup_rate INTO v_rate FROM exchange_rates ORDER BY fetched_at DESC LIMIT 1;
  END IF;
  IF v_rate IS NULL THEN
    SELECT (value #>> '{}')::NUMERIC INTO v_rate FROM platform_config WHERE key = 'exchange_rate_fallback_cup';
    v_rate := COALESCE(v_rate, 640.0);
  END IF;
  RETURN v_rate;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_current_exchange_rate() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_current_exchange_rate() TO PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_current_exchange_rate() TO anon;
GRANT EXECUTE ON FUNCTION public.get_current_exchange_rate() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_current_exchange_rate() TO service_role;

CREATE OR REPLACE FUNCTION public.get_driver_utilization()
 RETURNS TABLE(online integer, busy integer, idle integer, offline integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
#variable_conflict use_column
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'forbidden: admin only' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    COUNT(*) FILTER (WHERE dp.is_online = true)::INT AS online,
    COUNT(*) FILTER (WHERE dp.is_online = true AND EXISTS(
      SELECT 1 FROM rides r WHERE r.driver_id = dp.id AND r.status IN ('accepted','driver_en_route','arrived_at_pickup','in_progress')
    ))::INT AS busy,
    COUNT(*) FILTER (WHERE dp.is_online = true AND NOT EXISTS(
      SELECT 1 FROM rides r WHERE r.driver_id = dp.id AND r.status IN ('accepted','driver_en_route','arrived_at_pickup','in_progress')
    ))::INT AS idle,
    COUNT(*) FILTER (WHERE dp.is_online = false OR dp.is_online IS NULL)::INT AS offline
  FROM driver_profiles dp WHERE dp.status = 'approved';
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_driver_utilization() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_driver_utilization() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_driver_utilization() TO service_role;

CREATE OR REPLACE FUNCTION public.get_peak_hours(p_days_back integer DEFAULT 30)
 RETURNS TABLE(hour integer, avg_rides numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
#variable_conflict use_column
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'forbidden: admin only' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH hourly AS (
    SELECT EXTRACT(HOUR FROM r.created_at AT TIME ZONE 'America/Havana')::INT AS hour,
           (r.created_at AT TIME ZONE 'America/Havana')::DATE AS day,
           COUNT(*) AS rides
    FROM rides r
    WHERE r.created_at >= ((((now() AT TIME ZONE 'America/Havana')::date - p_days_back)::timestamp) AT TIME ZONE 'America/Havana')
    GROUP BY 1, 2
  )
  SELECT h.hour, ROUND(AVG(h.rides), 1) AS avg_rides FROM hourly h GROUP BY h.hour ORDER BY h.hour;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_peak_hours(integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_peak_hours(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_peak_hours(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.get_platform_config_numeric(p_key text, p_fallback numeric DEFAULT NULL::numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_raw JSONB;
  v_out NUMERIC;
BEGIN
  SELECT value INTO v_raw FROM platform_config WHERE key = p_key;
  IF v_raw IS NULL THEN
    RETURN p_fallback;
  END IF;

  -- `#>> '{}'` unwraps the JSONB scalar safely whether it was written
  -- as a string ('"0.15"') or as a JSON number (0.15). Cast to NUMERIC
  -- after.
  BEGIN
    v_out := (v_raw #>> '{}')::NUMERIC;
  EXCEPTION WHEN OTHERS THEN
    v_out := p_fallback;
  END;

  RETURN COALESCE(v_out, p_fallback);
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_platform_config_numeric(text,numeric) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_platform_config_numeric(text,numeric) TO service_role;

CREATE OR REPLACE FUNCTION public.get_platform_config_text(p_key text, p_fallback text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_raw JSONB;
BEGIN
  SELECT value INTO v_raw FROM platform_config WHERE key = p_key;
  IF v_raw IS NULL THEN
    RETURN p_fallback;
  END IF;
  RETURN COALESCE(v_raw #>> '{}', p_fallback);
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_platform_config_text(text,text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_platform_config_text(text,text) TO service_role;

CREATE OR REPLACE FUNCTION public.get_platform_earnings()
 RETURNS TABLE(platform_balance bigint, earnings_today bigint, earnings_this_week bigint, earnings_this_month bigint, commission_rate numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'America/Havana')::date;
  v_day_start timestamptz := (v_today::timestamp AT TIME ZONE 'America/Havana');
  v_week_start timestamptz := ((v_today - 7)::timestamp AT TIME ZONE 'America/Havana');
  v_month_start timestamptz := (date_trunc('month', v_today::timestamp) AT TIME ZONE 'America/Havana');
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  SELECT
    COALESCE((
      SELECT wa.balance FROM wallet_accounts wa
      WHERE wa.user_id = '00000000-0000-0000-0000-000000000001'
      AND wa.account_type = 'platform_revenue'
    ), 0)::BIGINT AS platform_balance,

    COALESCE((
      SELECT SUM(rps.commission_amount)
      FROM ride_pricing_snapshots rps
      JOIN rides r ON r.id = rps.ride_id
      WHERE r.status = 'completed'
      AND rps.snapshot_type = 'final'
      AND r.completed_at >= v_day_start
    ), 0)::BIGINT AS earnings_today,

    COALESCE((
      SELECT SUM(rps.commission_amount)
      FROM ride_pricing_snapshots rps
      JOIN rides r ON r.id = rps.ride_id
      WHERE r.status = 'completed'
      AND rps.snapshot_type = 'final'
      AND r.completed_at >= v_week_start
    ), 0)::BIGINT AS earnings_this_week,

    COALESCE((
      SELECT SUM(rps.commission_amount)
      FROM ride_pricing_snapshots rps
      JOIN rides r ON r.id = rps.ride_id
      WHERE r.status = 'completed'
      AND rps.snapshot_type = 'final'
      AND r.completed_at >= v_month_start
    ), 0)::BIGINT AS earnings_this_month,

    COALESCE((
      SELECT (pc.value #>> '{}')::NUMERIC FROM platform_config pc WHERE pc.key = 'commission_rate'
    ), 0.15) AS commission_rate;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_platform_earnings() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_platform_earnings() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_platform_earnings() TO service_role;

CREATE OR REPLACE FUNCTION public.get_product_failures(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c_system constant uuid[] := ARRAY['00000000-0000-0000-0000-000000000001',
                                    '00000000-0000-0000-0000-000000000099']::uuid[];
  v_days integer := LEAST(GREATEST(coalesce(p_days, 30), 1), 365);
  v_since timestamptz := now() - make_interval(days => v_days);
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'Admin only' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'days', v_days,
    -- Places riders asked for that the app did not have. 00584 queues a ride's pickup or dropoff
    -- venue (the text before the first comma) when no POI matches it, but not while a pending row
    -- of that name sits within ~200 m: a queue row is a place, not a request. So the demand is
    -- counted on the rides. A place is a queued name, compared without case, accents or outer
    -- spaces, shown with its latest spelling; it is listed when it was queued in the period or a
    -- ride of the period asked for it. rides: rides created in the period with that venue at
    -- either end; riders: their distinct customers. By name only: a ride to a place of the same
    -- name elsewhere counts too. last_seen: the later of its latest queue row and the latest of
    -- those rides (the panel shows it as last seen). imported: how many of its queue rows were
    -- imported (a count). Queue rows and rides of test and system accounts are left
    -- out; a queue row without a ride stays.
    'places_not_found', coalesce((
      WITH queued AS (
        SELECT lower(public.unaccent(btrim(q.name))) AS place, q.id, q.name, q.created_at, q.status
        FROM public.poi_import_queue q
        LEFT JOIN public.rides r ON r.id = q.ride_id
        LEFT JOIN public.users u ON u.id = r.customer_id
        WHERE NOT coalesce(u.is_test, false)
          AND (r.customer_id IS NULL OR r.customer_id <> ALL (c_system))
      ),
      places AS (
        SELECT place, left((array_agg(name ORDER BY created_at DESC, id DESC))[1], 80) AS name,
               max(created_at) AS last_queued,
               count(*) FILTER (WHERE status = 'done')::integer AS imported,
               bool_or(created_at >= v_since) AS queued_in_period
        FROM queued
        GROUP BY place
      ),
      -- One pass over the period's rides: the text before the first comma of each end, normalized
      -- the same way, kept when it names a place. _poi_leading_venue_name() returns that text or
      -- NULL, so below it only confirms these few ends are venues; MATERIALIZED keeps the planner
      -- from calling it on every end of every ride.
      ends AS MATERIALIZED (
        SELECT r.id, r.customer_id, r.created_at, e.addr, n.place
        FROM public.rides r
        JOIN public.users u ON u.id = r.customer_id
        CROSS JOIN LATERAL (VALUES (r.pickup_address), (r.dropoff_address)) AS e(addr)
        CROSS JOIN LATERAL (SELECT lower(public.unaccent(btrim(split_part(e.addr, ',', 1)))) AS place) AS n
        WHERE r.created_at >= v_since AND NOT u.is_test AND r.customer_id <> ALL (c_system)
          AND n.place IN (SELECT p.place FROM places p)
      ),
      demand AS (
        SELECT place, count(DISTINCT id)::integer AS rides, count(DISTINCT customer_id)::integer AS riders,
               max(created_at) AS last_ride
        FROM ends
        WHERE public._poi_leading_venue_name(addr) IS NOT NULL
        GROUP BY place
      )
      SELECT jsonb_agg(jsonb_build_object('name', x.name, 'rides', x.rides, 'riders', x.riders,
                                          'last_seen', x.last_seen, 'imported', x.imported)
                       ORDER BY x.rides DESC, x.last_seen DESC, x.name)
      FROM (
        SELECT p.name, coalesce(d.rides, 0) AS rides, coalesce(d.riders, 0) AS riders,
               GREATEST(p.last_queued, d.last_ride) AS last_seen, p.imported
        FROM places p
        LEFT JOIN demand d ON d.place = p.place
        WHERE p.queued_in_period OR d.place IS NOT NULL
        ORDER BY coalesce(d.rides, 0) DESC, GREATEST(p.last_queued, d.last_ride) DESC, p.name
        LIMIT 50
      ) x), '[]'::jsonb),
    -- The last push registration outcome per account and app (00585), reported in the period.
    'push_outcomes', coalesce((
      SELECT jsonb_agg(jsonb_build_object('app', x.app, 'outcome', x.outcome, 'users', x.users)
                       ORDER BY x.app, x.outcome)
      FROM (
        SELECT s.app, s.outcome, count(*)::integer AS users
        FROM public.push_registration_status s
        JOIN public.users u ON u.id = s.user_id
        WHERE s.updated_at >= v_since AND NOT u.is_test AND s.user_id <> ALL (c_system)
        GROUP BY s.app, s.outcome
      ) x), '[]'::jsonb),
    -- Of the people active in the period, how many have a device that can get a push.
    'push_reach', (
      SELECT jsonb_build_object(
        'riders_active', count(*),
        'riders_reachable', count(*) FILTER (WHERE EXISTS (
          SELECT 1 FROM public.user_devices d WHERE d.user_id = a.id)))
      FROM (
        SELECT DISTINCT r.customer_id AS id
        FROM public.rides r JOIN public.users u ON u.id = r.customer_id
        WHERE r.created_at >= v_since AND NOT u.is_test AND r.customer_id <> ALL (c_system)
      ) a
    ) || (
      SELECT jsonb_build_object(
        'drivers_active', count(*),
        'drivers_reachable', count(*) FILTER (WHERE EXISTS (
          SELECT 1 FROM public.user_devices d WHERE d.user_id = dp.user_id)))
      FROM public.driver_profiles dp JOIN public.users u ON u.id = dp.user_id
      WHERE dp.last_heartbeat_at >= v_since AND NOT u.is_test AND dp.user_id <> ALL (c_system)
    ),
    -- App versions opened in the period (00622). Empty until a build that reports opens is out.
    'app_versions', coalesce((
      SELECT jsonb_agg(jsonb_build_object('app', x.app, 'version', x.app_version,
                                          'platform', x.platform, 'installs', x.installs)
                       ORDER BY x.app, x.installs DESC)
      FROM (
        SELECT o.app, o.app_version, o.platform, count(*)::integer AS installs
        FROM public.app_opens o
        JOIN public.users u ON u.id = o.user_id
        WHERE o.last_opened_at >= v_since AND NOT u.is_test AND o.user_id <> ALL (c_system)
        GROUP BY o.app, o.app_version, o.platform
      ) x), '[]'::jsonb),
    -- Failed payments by reason: the provider's code, or else the start of the error message.
    'failed_payments', coalesce((
      SELECT jsonb_agg(jsonb_build_object('reason', x.reason, 'payments', x.payments,
                                          'last_seen', x.last_seen)
                       ORDER BY x.payments DESC, x.last_seen DESC, x.reason)
      FROM (
        SELECT left(coalesce(nullif(btrim(p.provider_error_code), ''),
                             nullif(btrim(p.error_message), ''), 'sin motivo'), 60) AS reason,
               count(*)::integer AS payments, max(p.created_at) AS last_seen
        FROM public.payment_intents p
        JOIN public.users u ON u.id = p.user_id
        WHERE p.status = 'failed' AND p.created_at >= v_since
          AND NOT u.is_test AND p.user_id <> ALL (c_system)
        GROUP BY 1
      ) x), '[]'::jsonb)
  );
END
$function$
;
REVOKE ALL ON FUNCTION public.get_product_failures(integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_product_failures(integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_product_failures(integer) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_rides_by_day(p_days_back integer DEFAULT 30)
 RETURNS TABLE(day date, total bigint, completed bigint, canceled bigint, revenue numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'America/Havana')::date;
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  SELECT d.day::DATE,
    COUNT(r.id) AS total,
    COUNT(r.id) FILTER (WHERE r.status = 'completed') AS completed,
    COUNT(r.id) FILTER (WHERE r.status = 'canceled') AS canceled,
    COALESCE(SUM(r.final_fare_cup) FILTER (WHERE r.status = 'completed'), 0)::numeric AS revenue
  FROM generate_series(v_today - (p_days_back - 1), v_today, '1 day'::INTERVAL) AS d(day)
  LEFT JOIN rides r ON (r.created_at AT TIME ZONE 'America/Havana')::DATE = d.day::DATE
  GROUP BY d.day
  ORDER BY d.day;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_rides_by_day(integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_rides_by_day(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_rides_by_day(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.get_rides_by_payment_method(p_days_back integer DEFAULT 30)
 RETURNS TABLE(payment_method text, count bigint, revenue numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_window_start timestamptz := (((now() AT TIME ZONE 'America/Havana')::date - p_days_back)::timestamp AT TIME ZONE 'America/Havana');
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
  SELECT
    r.payment_method::TEXT,
    COUNT(r.id) AS count,
    COALESCE(SUM(r.final_fare_cup), 0)::numeric AS revenue
  FROM rides r
  WHERE r.status = 'completed'
    AND r.completed_at >= v_window_start
  GROUP BY r.payment_method
  ORDER BY revenue DESC;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_rides_by_payment_method(integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_rides_by_payment_method(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_rides_by_payment_method(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.get_rides_by_service_type(p_days_back integer DEFAULT 30)
 RETURNS TABLE(service_type text, count bigint, revenue numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_window_start timestamptz := (((now() AT TIME ZONE 'America/Havana')::date - p_days_back)::timestamp AT TIME ZONE 'America/Havana');
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  RETURN QUERY
