    r.service_type::TEXT,
    COUNT(r.id) AS count,
    COALESCE(SUM(r.final_fare_cup), 0)::numeric AS revenue
  FROM rides r
  WHERE r.status = 'completed'
    AND r.completed_at >= v_window_start
  GROUP BY r.service_type
  ORDER BY revenue DESC;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_rides_by_service_type(integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_rides_by_service_type(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_rides_by_service_type(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.get_top_drivers(p_limit integer DEFAULT 10)
 RETURNS TABLE(driver_id uuid, driver_name text, rides_count bigint, rating numeric, revenue numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
#variable_conflict use_column
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RAISE EXCEPTION 'forbidden: admin only' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT
    dp.id AS driver_id,
    u.full_name AS driver_name,
    COALESCE(COUNT(*) FILTER (WHERE r.status = 'completed'), 0) AS rides_count,
    dp.rating_avg AS rating,
    COALESCE(SUM(r.final_fare_cup) FILTER (WHERE r.status = 'completed'), 0)::numeric AS revenue
  FROM driver_profiles dp
  JOIN users u ON u.id = dp.user_id
  LEFT JOIN rides r ON r.driver_id = dp.id
  WHERE dp.status = 'approved'
  GROUP BY dp.id, u.full_name, dp.rating_avg
  ORDER BY revenue DESC, rides_count DESC
  LIMIT p_limit;
END;
$function$
;
REVOKE ALL ON FUNCTION public.get_top_drivers(integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_top_drivers(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_top_drivers(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
BEGIN
  -- No JWT subject: anon, service role, cron, triggers without a user. None of
  -- them is an admin, and anon may not even call current_user_role().
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;
  RETURN public.current_user_role() IN ('admin', 'super_admin');
END;
$function$
;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_admin() TO PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_admin() TO anon;
GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_admin() TO service_role;

CREATE OR REPLACE FUNCTION public.is_corp_admin(p_account_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM corporate_employees
    WHERE corporate_account_id = p_account_id
      AND user_id = auth.uid()
      AND role = 'admin'
      AND is_active = true
  );
$function$
;
REVOKE ALL ON FUNCTION public.is_corp_admin(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_corp_admin(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_corp_admin(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.is_marketing()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  -- No JWT subject: anon, service role, cron. None of them is marketing, and anon may not
  -- call current_user_role() (00517). Same early return as is_admin() (00592).
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;
  RETURN public.current_user_role() = 'marketing';
END;
$function$
;
REVOKE ALL ON FUNCTION public.is_marketing() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_marketing() TO service_role;
GRANT EXECUTE ON FUNCTION public.is_marketing() TO anon;
GRANT EXECUTE ON FUNCTION public.is_marketing() TO authenticated;

CREATE OR REPLACE FUNCTION public.is_super_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM users
    WHERE id = auth.uid()
      AND role = 'super_admin'
  );
$function$
;
REVOKE ALL ON FUNCTION public.is_super_admin() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_super_admin() TO service_role;
GRANT EXECUTE ON FUNCTION public.is_super_admin() TO authenticated;

CREATE OR REPLACE FUNCTION public.list_team()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_uid uuid := public._team_require_super_admin();
BEGIN
  RETURN jsonb_build_object(
    'members', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'user_id', u.id,
          'full_name', coalesce(btrim(u.full_name), ''),
          'email', coalesce(m.email, nullif(btrim(u.email), '')),
          'role', u.role,
          'last_sign_in_at', au.last_sign_in_at,
          'gets_digest', m.email IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM public.team_digest_optouts o WHERE o.user_id = u.id AND o.opted_out),
          'is_me', u.id = v_uid)
        ORDER BY public._team_role_rank(u.role::text) DESC, lower(coalesce(u.full_name, '')), u.id)
      FROM public.users u
      LEFT JOIN auth.users au ON au.id = u.id
      LEFT JOIN public.mailable_user_emails(ARRAY(
        SELECT x.id FROM public.users x WHERE x.role IN ('super_admin', 'admin', 'marketing'))) m
        ON m.user_id = u.id
      WHERE u.role IN ('super_admin', 'admin', 'marketing')
        AND coalesce(u.is_active, true)
        AND u.id NOT IN ('00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000099')
    ), '[]'::jsonb),
    'invitations', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
          'id', i.id,
          'email', i.email,
          'role', i.role,
          'full_name', i.full_name,
          'invited_by_name', coalesce(btrim(inv.full_name), ''),
          'created_at', i.created_at,
          'expires_at', i.expires_at,
          'sent_at', i.sent_at,
          'expired', i.expires_at <= now(),
          'link', public._team_invitation_link(i.token))
        ORDER BY i.created_at DESC, i.id)
      FROM public.team_invitations i
      LEFT JOIN public.users inv ON inv.id = i.invited_by
      WHERE i.status = 'pending'
    ), '[]'::jsonb));
END;
$function$
;
REVOKE ALL ON FUNCTION public.list_team() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.list_team() TO service_role;
GRANT EXECUTE ON FUNCTION public.list_team() TO authenticated;

CREATE OR REPLACE FUNCTION public.mailable_user_emails(p_user_ids uuid[])
 RETURNS TABLE(user_id uuid, email text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT u.id, btrim(u.email)
  FROM public.users u
  WHERE u.id = ANY (p_user_ids)
    AND btrim(coalesce(u.email, '')) <> ''
    AND (
      u.email_verified_at IS NOT NULL
      OR EXISTS (
        SELECT 1
        FROM auth.identities i
        WHERE i.user_id = u.id
          AND i.provider IN ('google', 'apple')
          AND lower(i.identity_data->>'email_verified') = 'true'
          AND lower(btrim(i.identity_data->>'email')) = lower(btrim(u.email))
      )
    );
$function$
;
REVOKE ALL ON FUNCTION public.mailable_user_emails(uuid[]) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.mailable_user_emails(uuid[]) TO service_role;

CREATE OR REPLACE FUNCTION public.platform_config_can_read_secrets()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;
  RETURN COALESCE(is_admin(), false);
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$function$
;
REVOKE ALL ON FUNCTION public.platform_config_can_read_secrets() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.platform_config_can_read_secrets() TO PUBLIC;
GRANT EXECUTE ON FUNCTION public.platform_config_can_read_secrets() TO service_role;
GRANT EXECUTE ON FUNCTION public.platform_config_can_read_secrets() TO anon;
GRANT EXECUTE ON FUNCTION public.platform_config_can_read_secrets() TO authenticated;

CREATE OR REPLACE FUNCTION public.platform_config_is_secret(p_key text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT p_key NOT ILIKE '%publishable%'
     AND (
       p_key ~ '(_token|_secret|_signature|_hash|_api_key|_password)$'
       OR p_key IN (
         'eltoque_api_token',
         'infobip_api_key',
         'openweather_api_key',
         'smspm_token',
         'smspm_hash',
         'netopia_live_signature',
         'netopia_sandbox_signature'
       )
     );
$function$
;
REVOKE ALL ON FUNCTION public.platform_config_is_secret(text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.platform_config_is_secret(text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION public.platform_config_is_secret(text) TO service_role;

CREATE OR REPLACE FUNCTION public.process_dispute_refund(p_dispute_id uuid, p_admin_id uuid, p_refund_amount_trc integer, p_resolution text, p_resolution_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_dispute RECORD;
  v_ride RECORD;
  v_customer_account_id UUID;
  v_platform_account_id UUID;
  v_customer_balance INTEGER;
  v_platform_balance INTEGER;
  v_txn_id UUID;
  v_platform_user_id UUID := '00000000-0000-0000-0000-000000000001';
  v_new_status TEXT;
  v_caller_is_admin BOOLEAN;
BEGIN
  -- BUG-130 fix: caller must be platform admin/super_admin. We trust
  -- auth.uid() (set by Supabase from the JWT), NOT the p_admin_id
  -- argument which a malicious caller controls. p_admin_id stays as
  -- the ledger created_by for traceability when admin tools intend
  -- to attribute the action to a specific admin.
  SELECT (role IN ('admin','super_admin'))
    INTO v_caller_is_admin
  FROM users WHERE id = auth.uid();

  IF NOT COALESCE(v_caller_is_admin, false) THEN
    RAISE EXCEPTION 'Forbidden: admin role required to process dispute refunds';
  END IF;

  SELECT * INTO v_dispute FROM ride_disputes WHERE id = p_dispute_id FOR UPDATE;
  IF v_dispute IS NULL THEN
    RAISE EXCEPTION 'Dispute not found: %', p_dispute_id;
  END IF;

  IF v_dispute.status IN ('resolved_rider', 'resolved_driver', 'closed') THEN
    RAISE EXCEPTION 'Dispute % is already resolved (status: %)', p_dispute_id, v_dispute.status;
  END IF;

  SELECT * INTO v_ride FROM rides WHERE id = v_dispute.ride_id FOR UPDATE;
  IF v_ride IS NULL THEN
    RAISE EXCEPTION 'Ride not found for dispute: %', v_dispute.ride_id;
  END IF;

  IF p_refund_amount_trc < 0 THEN
    RAISE EXCEPTION 'Refund amount cannot be negative';
  END IF;

  IF p_refund_amount_trc > COALESCE(v_ride.final_fare_trc, 0) THEN
    RAISE EXCEPTION 'Refund (%) exceeds ride fare (%)',
      p_refund_amount_trc, COALESCE(v_ride.final_fare_trc, 0);
  END IF;

  IF p_refund_amount_trc > 0 THEN
    v_customer_account_id := ensure_wallet_account(v_ride.customer_id, 'customer_cash');
    v_platform_account_id := ensure_wallet_account(v_platform_user_id, 'platform_revenue');

    SELECT balance INTO v_customer_balance FROM wallet_accounts WHERE id = v_customer_account_id FOR UPDATE;
    SELECT balance INTO v_platform_balance FROM wallet_accounts WHERE id = v_platform_account_id FOR UPDATE;

    INSERT INTO ledger_transactions (id, idempotency_key, type, status, reference_type, reference_id, description, created_by)
    VALUES (gen_random_uuid(), 'dispute_refund:' || p_dispute_id::TEXT,
            'adjustment', 'posted', 'ride', v_ride.id,
            'Reembolso disputa viaje #' || LEFT(v_ride.id::TEXT, 8), p_admin_id)
    RETURNING id INTO v_txn_id;

    INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
    VALUES (v_txn_id, v_customer_account_id, p_refund_amount_trc, v_customer_balance + p_refund_amount_trc);

    INSERT INTO ledger_entries (transaction_id, account_id, amount, balance_after)
    VALUES (v_txn_id, v_platform_account_id, -p_refund_amount_trc, v_platform_balance - p_refund_amount_trc);

    UPDATE wallet_accounts SET balance = balance + p_refund_amount_trc WHERE id = v_customer_account_id;
    UPDATE wallet_accounts SET balance = balance - p_refund_amount_trc WHERE id = v_platform_account_id;
  END IF;

  v_new_status := CASE p_resolution
    WHEN 'full_refund'    THEN 'resolved_rider'
    WHEN 'partial_refund' THEN 'resolved_rider'
    WHEN 'credit'         THEN 'resolved_rider'
    WHEN 'no_action'      THEN 'resolved_driver'
    WHEN 'warning_issued' THEN 'resolved_driver'
    ELSE 'closed'
  END;

  UPDATE ride_disputes SET
    status = v_new_status,
    resolution = p_resolution,
    resolution_notes = p_resolution_notes,
    refund_amount_trc = p_refund_amount_trc,
    refund_transaction_id = v_txn_id,
    resolved_at = NOW(),
    updated_at = NOW()
  WHERE id = p_dispute_id;

  IF v_ride.status = 'disputed' THEN
    UPDATE rides SET status = 'completed', updated_at = NOW() WHERE id = v_ride.id;
  END IF;

  RETURN COALESCE(v_txn_id, '00000000-0000-0000-0000-000000000000'::UUID);
END;
$function$
;
REVOKE ALL ON FUNCTION public.process_dispute_refund(uuid,uuid,integer,text,text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.process_dispute_refund(uuid,uuid,integer,text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.process_dispute_refund(uuid,uuid,integer,text,text) TO service_role;

CREATE OR REPLACE FUNCTION public.promote_user_role(p_target_user_id uuid, p_new_role public.user_role, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_caller_uid uuid;
  v_old_role   user_role;
BEGIN
  v_caller_uid := auth.uid();

  IF v_caller_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;

  IF NOT is_super_admin() THEN
    RAISE EXCEPTION 'forbidden: only super_admin can promote user roles';
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 10 THEN
    RAISE EXCEPTION 'reason required (min 10 chars)';
  END IF;

  IF p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'p_target_user_id required';
  END IF;

  IF p_new_role IS NULL THEN
    RAISE EXCEPTION 'p_new_role required';
  END IF;

  SELECT role INTO v_old_role FROM users WHERE id = p_target_user_id;
  IF v_old_role IS NULL THEN
    RAISE EXCEPTION 'target user not found: %', p_target_user_id;
  END IF;

  IF v_old_role = p_new_role THEN
    RETURN jsonb_build_object(
      'success', true,
      'no_change', true,
      'target_user_id', p_target_user_id,
      'role', p_new_role
    );
  END IF;

  UPDATE users SET role = p_new_role WHERE id = p_target_user_id;

  INSERT INTO admin_actions (admin_id, action, target_type, target_id, reason)
  VALUES (
    v_caller_uid,
    'promote_user_role',
    'user',
    p_target_user_id::TEXT,
    p_reason || ' [from=' || v_old_role || ' to=' || p_new_role || ']'
  );

  RETURN jsonb_build_object(
    'success', true,
    'target_user_id', p_target_user_id,
    'old_role', v_old_role,
    'new_role', p_new_role,
    'reason', p_reason
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.promote_user_role(uuid,public.user_role,text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.promote_user_role(uuid,public.user_role,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.promote_user_role(uuid,public.user_role,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.recompute_user_rating(p_user_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_window_days numeric := get_platform_config_numeric('cancel_rating_event_window_days', 90);
  v_sum numeric;
  v_cnt numeric;
BEGIN
  SELECT COALESCE(SUM(s.val), 0), COUNT(s.val)
    INTO v_sum, v_cnt
  FROM (
    SELECT r.rating::numeric AS val
    FROM reviews r
    WHERE r.reviewee_id = p_user_id
      AND r.is_visible = true
    UNION ALL
    SELECT ce.rating_value AS val
    FROM cancellation_rating_events ce
    WHERE ce.user_id = p_user_id
      AND ce.rating_value IS NOT NULL
      AND (v_window_days <= 0
           OR ce.created_at > now() - (v_window_days || ' days')::interval)
  ) s;

  IF v_cnt = 0 THEN
    RETURN 5.00;
  END IF;
  RETURN GREATEST(1.00, LEAST(5.00, ROUND(v_sum / v_cnt, 2)));
END;
$function$
;
REVOKE ALL ON FUNCTION public.recompute_user_rating(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.recompute_user_rating(uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION public.recompute_user_rating(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.remove_team_member(p_user uuid, p_reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_uid    uuid;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_old    public.user_role;
  v_new    public.user_role;
BEGIN
  PERFORM public._team_require_super_admin();
  IF char_length(v_reason) < 5 THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'Escribe el motivo (al menos 5 caracteres).', DETAIL = 'team_reason_required';
  END IF;
  PERFORM 1 FROM public.users WHERE role = 'super_admin' ORDER BY id FOR NO KEY UPDATE;
  v_uid := public._team_require_super_admin();
  v_old := public._team_lock_target(v_uid, p_user);
  IF v_old = 'super_admin' THEN
    PERFORM public._team_check_last_super_admin(p_user);
  END IF;
  v_new := public._team_previous_role(p_user);
  PERFORM public._team_write_role(p_user, v_new);
  PERFORM public._team_cancel_pending_for(p_user, v_uid);
  INSERT INTO public.admin_actions (admin_id, action, target_type, target_id, old_values, new_values, reason)
  VALUES (v_uid, 'team_member_removed', 'user', p_user::text,
          jsonb_build_object('role', v_old), jsonb_build_object('role', v_new), v_reason);
  RETURN v_new::text;
END;
$function$
;
REVOKE ALL ON FUNCTION public.remove_team_member(uuid,text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.remove_team_member(uuid,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.remove_team_member(uuid,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.review_is_public(p_review_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  -- 00645: a visible review of the ride's driver, read by a signed-in user.
  SELECT auth.uid() IS NOT NULL AND EXISTS (
    SELECT 1
    FROM reviews rv
    JOIN rides r ON r.id = rv.ride_id
    JOIN driver_profiles dp ON dp.id = r.driver_id
    WHERE rv.id = p_review_id
      AND rv.is_visible = true
      AND dp.user_id = rv.reviewee_id
  );
$function$
;
REVOKE ALL ON FUNCTION public.review_is_public(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.review_is_public(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.review_is_public(uuid) TO anon;
GRANT EXECUTE ON FUNCTION public.review_is_public(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.set_referral_amounts(p_amounts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  c_keys constant text[] := ARRAY['referral_bonus_cup', 'referral_bonus_driver_cup',
    'referral_welcome_bonus_cup', 'referral_welcome_bonus_driver_cup'];
  v_key text;
  v_val jsonb;
  v_num numeric;
BEGIN
  IF NOT (public.is_admin() OR public.is_marketing()) THEN
    RETURN jsonb_build_object('error', 'forbidden');
  END IF;
  IF p_amounts IS NULL OR jsonb_typeof(p_amounts) IS DISTINCT FROM 'object' OR p_amounts = '{}'::jsonb THEN
    RETURN jsonb_build_object('error', 'nothing_to_save');
  END IF;

  -- Everything is checked before anything is written.
  FOR v_key, v_val IN SELECT e.key, e.value FROM jsonb_each(p_amounts) AS e LOOP
    IF NOT (v_key = ANY (c_keys)) THEN
      RETURN jsonb_build_object('error', 'unknown_key', 'key', v_key);
    END IF;
    IF jsonb_typeof(v_val) IS DISTINCT FROM 'number' THEN
      RETURN jsonb_build_object('error', 'invalid_amount', 'key', v_key);
    END IF;
    v_num := (v_val #>> '{}')::numeric;
    -- No cap (owner, 2026-10-19), but an integer the referral triggers can read as one.
    IF v_num < 0 OR v_num <> trunc(v_num) OR v_num > 2147483647 THEN
      RETURN jsonb_build_object('error', 'invalid_amount', 'key', v_key);
    END IF;
  END LOOP;

  -- tg_platform_config_audit logs each changed value with auth.uid(); an equal value writes nothing.
  FOR v_key, v_val IN SELECT e.key, e.value FROM jsonb_each(p_amounts) AS e LOOP
    INSERT INTO public.platform_config AS pc (key, value)
    VALUES (v_key, to_jsonb((v_val #>> '{}')::numeric::bigint))
    ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now()
     WHERE pc.value IS DISTINCT FROM EXCLUDED.value;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'amounts',
    (SELECT jsonb_object_agg(k.key, COALESCE(pc.value, '0'::jsonb))
       FROM unnest(c_keys) AS k(key)
       LEFT JOIN public.platform_config pc ON pc.key = k.key));
END;
$function$
;
REVOKE ALL ON FUNCTION public.set_referral_amounts(jsonb) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.set_referral_amounts(jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.set_referral_amounts(jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.set_team_member_role(p_user uuid, p_role text, p_reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_uid    uuid;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_old    public.user_role;
BEGIN
  PERFORM public._team_require_super_admin();
  IF p_role IS NULL OR p_role NOT IN ('super_admin', 'admin', 'marketing') THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'El rol tiene que ser superadministrador, administrador o marketing.', DETAIL = 'team_bad_role';
  END IF;
  IF char_length(v_reason) < 5 THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'Escribe el motivo (al menos 5 caracteres).', DETAIL = 'team_reason_required';
  END IF;
  -- Team changes run one at a time: two super_admins demoting each other at once
  -- could otherwise leave none. NO KEY UPDATE, not UPDATE: an accept writes admin_actions,
  -- whose foreign key share-locks the inviter's row, and must not wait on this.
  PERFORM 1 FROM public.users WHERE role = 'super_admin' ORDER BY id FOR NO KEY UPDATE;
  v_uid := public._team_require_super_admin();
  v_old := public._team_lock_target(v_uid, p_user);
  PERFORM public._team_cancel_pending_for(p_user, v_uid);
  IF v_old::text = p_role THEN
    RETURN p_role;
  END IF;
  IF v_old = 'super_admin' THEN
    PERFORM public._team_check_last_super_admin(p_user);
  END IF;
  PERFORM public._team_write_role(p_user, p_role::public.user_role);
  INSERT INTO public.admin_actions (admin_id, action, target_type, target_id, old_values, new_values, reason)
  VALUES (v_uid, 'team_role_changed', 'user', p_user::text,
          jsonb_build_object('role', v_old), jsonb_build_object('role', p_role), v_reason);
  RETURN p_role;
END;
$function$
;
REVOKE ALL ON FUNCTION public.set_team_member_role(uuid,text,text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.set_team_member_role(uuid,text,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.set_team_member_role(uuid,text,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.team_digest_recipients()
 RETURNS TABLE(user_id uuid, role text, email text, full_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
#variable_conflict use_column
DECLARE
  c_platform CONSTANT uuid := '00000000-0000-0000-0000-000000000001';
  v_preview text := lower(btrim(coalesce(public.get_platform_config_text('team_digest_preview_to', ''), '')));
BEGIN
  RETURN QUERY
  WITH staff AS (
    SELECT u.id, u.role::text AS role, coalesce(btrim(u.full_name), '') AS full_name
    FROM public.users u
    WHERE u.role IN ('super_admin', 'admin', 'marketing')
      AND coalesce(u.is_active, true)
      AND u.id <> c_platform
      AND NOT EXISTS (SELECT 1 FROM public.team_digest_optouts o WHERE o.user_id = u.id AND o.opted_out)
      AND (v_preview = '' OR lower(btrim(u.id::text)) = v_preview)
  )
  SELECT s.id, s.role, m.email, s.full_name
  FROM staff s
  JOIN public.mailable_user_emails(ARRAY(SELECT s2.id FROM staff s2)) m ON m.user_id = s.id
  ORDER BY s.role, s.id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.team_digest_recipients() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.team_digest_recipients() TO service_role;

CREATE OR REPLACE FUNCTION public.unfreeze_wallet(p_user_id uuid, p_admin_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF auth.uid() <> p_admin_id OR NOT is_admin() THEN
    RAISE EXCEPTION 'Forbidden: admin role required (and p_admin_id must match caller)';
  END IF;

  UPDATE wallet_accounts
  SET is_frozen = false, frozen_reason = NULL,
      frozen_at = NULL, frozen_by = NULL
  WHERE user_id = p_user_id;

  INSERT INTO admin_actions (admin_id, action, target_type, target_id)
  VALUES (p_admin_id, 'unfreeze_wallet', 'user', p_user_id);
  RETURN true;
END;
$function$
;
REVOKE ALL ON FUNCTION public.unfreeze_wallet(uuid,uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.unfreeze_wallet(uuid,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.unfreeze_wallet(uuid,uuid) TO service_role;

-- 4. Views
CREATE VIEW public.driver_churn_risk WITH (security_invoker=true) AS
 SELECT dp.id AS driver_profile_id,
    dp.user_id,
    u.full_name,
    dp.rating_avg,
    dp.total_rides_completed,
    dp.acceptance_rate,
    dp.is_online,
    dp.status,
    (COALESCE(EXTRACT(days FROM (now() - ( SELECT max(r.completed_at) AS max
           FROM public.rides r
          WHERE ((r.driver_id = dp.id) AND (r.status = 'completed'::public.ride_status))))), (999)::numeric))::integer AS days_since_last_ride,
    (COALESCE(( SELECT sum(r.final_fare_cup) AS sum
           FROM public.rides r
          WHERE ((r.driver_id = dp.id) AND (r.status = 'completed'::public.ride_status) AND (r.completed_at > (now() - '7 days'::interval)))), (0)::bigint))::integer AS earnings_this_week,
    (COALESCE(( SELECT sum(r.final_fare_cup) AS sum
           FROM public.rides r
          WHERE ((r.driver_id = dp.id) AND (r.status = 'completed'::public.ride_status) AND (r.completed_at >= (now() - '14 days'::interval)) AND (r.completed_at <= (now() - '7 days'::interval)))), (0)::bigint))::integer AS earnings_last_week,
    LEAST(100, GREATEST(0, ((LEAST(40, ((COALESCE(EXTRACT(days FROM (now() - ( SELECT max(r.completed_at) AS max
           FROM public.rides r
          WHERE ((r.driver_id = dp.id) AND (r.status = 'completed'::public.ride_status))))), (30)::numeric))::integer * 2)) +
        CASE
            WHEN (COALESCE(dp.rating_avg, (5)::numeric) < 3.5) THEN 20
            WHEN (COALESCE(dp.rating_avg, (5)::numeric) < 4.0) THEN 10
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE(dp.acceptance_rate, (100)::numeric) < (50)::numeric) THEN 20
            WHEN (COALESCE(dp.acceptance_rate, (100)::numeric) < (70)::numeric) THEN 10
            ELSE 0
        END))) AS churn_risk_score,
        CASE
            WHEN (LEAST(100, GREATEST(0, ((LEAST(40, ((COALESCE(EXTRACT(days FROM (now() - ( SELECT max(r.completed_at) AS max
               FROM public.rides r
              WHERE ((r.driver_id = dp.id) AND (r.status = 'completed'::public.ride_status))))), (30)::numeric))::integer * 2)) +
            CASE
                WHEN (COALESCE(dp.rating_avg, (5)::numeric) < 3.5) THEN 20
                WHEN (COALESCE(dp.rating_avg, (5)::numeric) < 4.0) THEN 10
                ELSE 0
            END) +
            CASE
                WHEN (COALESCE(dp.acceptance_rate, (100)::numeric) < (50)::numeric) THEN 20
                WHEN (COALESCE(dp.acceptance_rate, (100)::numeric) < (70)::numeric) THEN 10
                ELSE 0
            END))) >= 50) THEN 'high'::text
            WHEN (LEAST(100, GREATEST(0, (LEAST(40, ((COALESCE(EXTRACT(days FROM (now() - ( SELECT max(r.completed_at) AS max
               FROM public.rides r
              WHERE ((r.driver_id = dp.id) AND (r.status = 'completed'::public.ride_status))))), (30)::numeric))::integer * 2)) +
            CASE
                WHEN (COALESCE(dp.rating_avg, (5)::numeric) < 3.5) THEN 20
                WHEN (COALESCE(dp.rating_avg, (5)::numeric) < 4.0) THEN 10
                ELSE 0
            END))) >= 25) THEN 'medium'::text
            ELSE 'low'::text
        END AS risk_level
   FROM (public.driver_profiles dp
     LEFT JOIN public.users u ON ((u.id = dp.user_id)))
  WHERE (dp.status = 'approved'::public.driver_status);
REVOKE ALL ON public.driver_churn_risk FROM anon, authenticated, service_role;
GRANT INSERT ON public.driver_churn_risk TO anon;
GRANT UPDATE ON public.driver_churn_risk TO anon;
GRANT DELETE ON public.driver_churn_risk TO anon;
GRANT TRUNCATE ON public.driver_churn_risk TO anon;
GRANT REFERENCES ON public.driver_churn_risk TO anon;
GRANT TRIGGER ON public.driver_churn_risk TO anon;
GRANT INSERT ON public.driver_churn_risk TO authenticated;
GRANT SELECT ON public.driver_churn_risk TO authenticated;
GRANT UPDATE ON public.driver_churn_risk TO authenticated;
GRANT DELETE ON public.driver_churn_risk TO authenticated;
GRANT TRUNCATE ON public.driver_churn_risk TO authenticated;
GRANT REFERENCES ON public.driver_churn_risk TO authenticated;
GRANT TRIGGER ON public.driver_churn_risk TO authenticated;
GRANT INSERT ON public.driver_churn_risk TO service_role;
GRANT SELECT ON public.driver_churn_risk TO service_role;
GRANT UPDATE ON public.driver_churn_risk TO service_role;
GRANT DELETE ON public.driver_churn_risk TO service_role;
