   FROM public._panel_driver_churn_risk() c(driver_profile_id, user_id, full_name, rating_avg, total_rides_completed, acceptance_rate, is_online, status, days_since_last_ride, churn_risk_score, risk_level)
  WHERE (( SELECT public.is_admin() AS is_admin) OR ( SELECT public.is_marketing() AS is_marketing));
