CREATE VIEW public.panel_driver_profiles WITH (security_barrier=true, security_invoker=false) AS
 SELECT dp.id,
    dp.user_id,
    dp.is_online,
    dp.total_rides_completed,
    dp.total_rides,
    dp.status,
    dp.rating_avg,
    dp.acceptance_rate,
    dp.total_rides_offered,
    dp.city_id,
    dp.zone_id,
    dp.municipality,
    dp.province,
    dp.created_at,
    dp.approved_at,
    dp.suspended_at,
    dp.suspended_reason,
    dp.is_on_break,
    dp.auto_accept_enabled,
    dp.last_heartbeat_at,
    dp.auto_offline_at,
    dp.terms_accepted_at,
    u.full_name,
    u.phone,
    u.email,
    v.type AS vehicle_type,
    v.plate_number,
    v.make AS vehicle_make,
    v.model AS vehicle_model,
    v.color AS vehicle_color,
    v.year AS vehicle_year
   FROM ((public.driver_profiles dp
     JOIN public.users u ON ((u.id = dp.user_id)))
     LEFT JOIN LATERAL ( SELECT vh.type,
            vh.plate_number,
            vh.make,
            vh.model,
            vh.color,
            vh.year
           FROM public.vehicles vh
          WHERE ((vh.driver_id = dp.id) AND vh.is_active)
          ORDER BY vh.created_at DESC, vh.id DESC
         LIMIT 1) v ON (true))
  WHERE (( SELECT public.is_admin() AS is_admin) OR ( SELECT public.is_marketing() AS is_marketing));
REVOKE ALL ON public.panel_driver_profiles FROM anon, authenticated, service_role;
