CREATE VIEW public.panel_ride_disputes WITH (security_barrier=true, security_invoker=false) AS
 SELECT id,
    ride_id,
    opened_by,
    reason,
    description,
    status,
    priority,
    respondent_id,
    respondent_message,
    respondent_replied_at,
    resolution,
    resolution_notes,
    assigned_to,
    sla_first_response_at,
    sla_resolution_deadline,
    support_ticket_id,
    incident_report_id,
    created_at,
    updated_at,
    resolved_at
   FROM public.ride_disputes d
  WHERE (( SELECT public.is_admin() AS is_admin) OR ( SELECT public.is_marketing() AS is_marketing));
REVOKE ALL ON public.panel_ride_disputes FROM anon, authenticated, service_role;
GRANT SELECT ON public.panel_ride_disputes TO authenticated;
GRANT SELECT ON public.panel_ride_disputes TO service_role;

CREATE VIEW public.panel_rides WITH (security_barrier=true, security_invoker=false) AS
 SELECT id,
    created_at,
    status,
    customer_id,
    driver_id,
    service_type,
    city_id,
    estimated_fare_cup,
    final_fare_cup,
    final_fare_trc,
    payment_method,
    pickup_address,
    dropoff_address,
    promo_code_id,
    discount_amount_cup,
    shared_ride_discount_cup,
    dispatch_round,
    ride_mode,
    is_scheduled,
    scheduled_at,
    accepted_at,
    driver_arrived_at,
    pickup_at,
    arrived_at_destination_at,
    completed_at,
    canceled_at,
    canceled_by,
        CASE
            WHEN (status <> 'canceled'::public.ride_status) THEN NULL::text
            WHEN (canceled_by IS NULL) THEN 'system'::text
            WHEN (canceled_by = customer_id) THEN 'customer'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.driver_profiles d
              WHERE ((d.id = r.driver_id) AND (d.user_id = r.canceled_by)))) THEN 'driver'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.users u
              WHERE ((u.id = r.canceled_by) AND (u.role = ANY (ARRAY['admin'::public.user_role, 'super_admin'::public.user_role]))))) THEN 'staff'::text
            ELSE 'unknown'::text
        END AS canceled_by_role,
    cancellation_reason,
    cancellation_reason_code,
    estimated_distance_m,
    actual_distance_m,
    estimated_duration_s,
    actual_duration_s,
    wait_time_minutes,
    wait_time_charge_cup,
    passenger_count,
    shared_ride,
    is_split,
    corporate_account_id,
    partner_place_id,
    partner_discount_cup,
    tip_amount,
    surge_multiplier,
    driver_gps_status,
    searching_seen_at,
    last_dispatched_at,
    payment_status
   FROM public.rides r
  WHERE (( SELECT public.is_admin() AS is_admin) OR ( SELECT public.is_marketing() AS is_marketing));
REVOKE ALL ON public.panel_rides FROM anon, authenticated, service_role;
GRANT SELECT ON public.panel_rides TO authenticated;
GRANT SELECT ON public.panel_rides TO service_role;

