  WHERE ((r.id = ride_waypoints.ride_id) AND ((r.customer_id = auth.uid()) OR (r.driver_id IN ( SELECT driver_profiles.id
           FROM public.driver_profiles
          WHERE (driver_profiles.user_id = auth.uid()))))))));
CREATE POLICY ride_waypoints_customer_delete ON public.ride_waypoints AS PERMISSIVE FOR DELETE TO public USING ((EXISTS ( SELECT 1
   FROM public.rides r
  WHERE ((r.id = ride_waypoints.ride_id) AND (r.customer_id = auth.uid())))));
CREATE POLICY ride_waypoints_customer_insert ON public.ride_waypoints AS PERMISSIVE FOR INSERT TO public WITH CHECK ((EXISTS ( SELECT 1
   FROM public.rides r
  WHERE ((r.id = ride_waypoints.ride_id) AND (r.customer_id = auth.uid())))));
CREATE POLICY ride_waypoints_customer_update ON public.ride_waypoints AS PERMISSIVE FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM public.rides r
  WHERE ((r.id = ride_waypoints.ride_id) AND (r.customer_id = auth.uid()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.rides r
  WHERE ((r.id = ride_waypoints.ride_id) AND (r.customer_id = auth.uid())))));
CREATE POLICY ride_waypoints_driver_update ON public.ride_waypoints AS PERMISSIVE FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM (public.rides r
     JOIN public.driver_profiles dp ON ((dp.id = r.driver_id)))
  WHERE ((r.id = ride_waypoints.ride_id) AND (dp.user_id = auth.uid()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM (public.rides r
     JOIN public.driver_profiles dp ON ((dp.id = r.driver_id)))
  WHERE ((r.id = ride_waypoints.ride_id) AND (dp.user_id = auth.uid())))));
CREATE POLICY r_admin_select ON public.rides AS PERMISSIVE FOR SELECT TO public USING (public.is_admin());
CREATE POLICY r_insert ON public.rides AS PERMISSIVE FOR INSERT TO public WITH CHECK ((customer_id = ( SELECT auth.uid() AS uid)));
CREATE POLICY r_select_customer ON public.rides AS PERMISSIVE FOR SELECT TO public USING (((customer_id = ( SELECT auth.uid() AS uid)) OR public.is_admin()));
CREATE POLICY r_select_driver ON public.rides AS PERMISSIVE FOR SELECT TO public USING (((driver_id IN ( SELECT driver_profiles.id
   FROM public.driver_profiles
  WHERE (driver_profiles.user_id = ( SELECT auth.uid() AS uid)))) OR (EXISTS ( SELECT 1
   FROM public.ride_offers o
  WHERE ((o.ride_id = rides.id) AND (o.driver_profile_id IN ( SELECT driver_profiles.id
           FROM public.driver_profiles
          WHERE (driver_profiles.user_id = ( SELECT auth.uid() AS uid)))) AND (o.status = 'pending'::text) AND (o.expires_at > now()))))));
CREATE POLICY r_update ON public.rides AS PERMISSIVE FOR UPDATE TO public USING (((customer_id = ( SELECT auth.uid() AS uid)) OR (driver_id IN ( SELECT driver_profiles.id
   FROM public.driver_profiles
  WHERE (driver_profiles.user_id = ( SELECT auth.uid() AS uid)))) OR public.is_admin()));
CREATE POLICY sc_admin_select ON public.selfie_checks AS PERMISSIVE FOR SELECT TO authenticated USING (public.is_admin());
